window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["nucleic"]={"id": "nucleic", "title": "核酸代谢", "sub": "38页教材逐页详解 · 30张概念图 · 32道考题", "sub2": "嘌呤/嘧啶核苷酸代谢 · 从头合成与补救", "modules": [{"i": 0, "name": "模块一：核酸/核苷酸分解", "slides": [{"i": 0, "sec": "核酸代谢", "title": "第九章 核酸的酶促降解和核苷酸代谢 (p1)", "notes": "第九章 核酸的酶促降解和核苷酸代谢。\u000b内容：第一节 核酸和核苷酸的分解代谢(核酸酶降解→核苷酸→核苷→碱基→终产物)；\u000b第二节 核苷酸的合成代谢(嘌呤/嘧啶的从头合成+补救途径+脱氧核苷酸合成)。", "page": 1, "level": "掌握", "img": "assets/img/nucleic/p001.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "核酸代谢", "title": "第一节-分解代谢总览 (p2-p3) (p2)", "notes": "第一节 核酸和核苷酸的分解代谢。\u000b总览：核酸→核酸酶→核苷酸→核苷酸酶→核苷→核苷磷酸化酶→碱基+戊糖。\u000b嘌呤→尿酸；\u000b嘧啶→NH3+CO2+β-丙氨酸类。\u000b戊糖→戊糖-1-P→戊糖-5-P→进入PPP代谢。", "page": 2, "level": "掌握", "img": "assets/img/nucleic/p002.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "核酸代谢", "title": "核酸酶的分类 (p4)", "notes": "一、多核苷酸的分解-核酸酶。\u000b按底物：核糖核酸酶(RNase)/脱氧核糖核酸酶(DNase)。\u000b按作用位点：核酸内切酶(切分子内部)/核酸外切酶(从末端逐个切)。\u000b举例：蛇毒磷酸二酯酶→5'-核苷酸；\u000b牛脾磷酸二酯酶→3'-核苷酸。", "page": 4, "level": "掌握", "img": "assets/img/nucleic/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "核酸代谢", "title": "限制性核酸内切酶 (p5)", "notes": "限制性核酸内切酶(Restriction enzyme)：识别特定DNA序列并切割。\u000b例：EcoRⅠ识别GAATTC→切G/AATTC；\u000bDNaseⅠ/DNaseⅡ非特异性；\u000bRNaseⅠ水解RNA。\u000b限制酶是基因工程的分子剪刀(分子克隆的核心工具)。", "page": 5, "level": "掌握", "img": "assets/img/nucleic/p005.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "核酸代谢", "title": "核苷酸和核苷的分解 (p6)", "notes": "二、单核苷酸和核苷的分解。\u000b①核苷酸酶(磷酸单酯酶)→核苷+Pi(5'-核苷酸酶/3'-核苷酸酶特异)。\u000b②核苷→核苷磷酸化酶→碱基+戊糖-1-磷酸(主要)。\u000b或核苷水解酶(植物)→碱基+戊糖。\u000b核苷酸酶有特异性和非特异性两类。", "page": 6, "level": "掌握", "img": "assets/img/nucleic/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "核酸代谢", "title": "嘌呤的分解-尿酸生成 (p7-p8) (p6)", "notes": "三、嘌呤和嘧啶的分解。\u000b1.嘌呤分解：核苷酸→核苷→碱基三个水平降解。\u000b腺苷酸→次黄苷酸→腺嘌呤→次黄嘌呤→黄嘌呤→尿酸；\u000b鸟苷酸→鸟苷→鸟嘌呤→黄嘌呤→尿酸。\u000b关键酶：腺嘌呤/腺苷/腺苷酸脱氨酶→次黄嘌呤；\u000b鸟嘌呤/鸟苷/鸟苷酸脱氨酶→黄嘌呤。\u000b终产物尿酸。", "page": 6, "level": "掌握", "img": "assets/img/nucleic/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "核酸代谢", "title": "嘌呤分解-先脱氨后氧化 (p9)", "notes": "嘌呤分解关键路径：腺苷→腺苷脱氨酶→次黄苷+NH3→核糖磷酸化酶→次黄嘌呤+核糖-1-P→黄嘌呤氧化酶→黄嘌呤→黄嘌呤氧化酶→尿酸。\u000b鸟嘌呤→鸟嘌呤脱氨酶→黄嘌呤→尿酸。\u000b原则：先脱氨后氧化。\u000b黄嘌呤氧化酶含FAD/钼/铁-硫簇→催化最后两步→H2O2副产物。", "page": 9, "level": "掌握", "img": "assets/img/nucleic/p009.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "核酸代谢", "title": "痛风症与别嘌呤醇 (p10)", "notes": "痛风症：尿酸过多积累→形成尿酸钠结晶→沉积关节→剧烈疼痛。\u000b治疗：别嘌呤醇(Allopurinol)→黄嘌呤氧化酶竞争性抑制剂→抑制黄嘌呤→尿酸。\u000b别嘌呤醇本身被氧化为别黄嘌呤(仍结合酶→不可逆抑制)。\u000b乔治·希金斯(Hitchings)+格特鲁德·伊莉昂(Elion)开发。", "page": 10, "level": "掌握", "img": "assets/img/nucleic/p010.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "nucleic_mcq_1", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "核酸酶按作用位点分为哪两类？", "o": ["A. RNase和DNase", "B. 核酸内切酶和核酸外切酶", "C. 核苷酸酶和核苷酶", "D. 磷酸二酯酶和磷酸单酯酶"], "a": "B", "e": "按作用位点：内切酶(切内部)/外切酶(从末端)。按底物：RNase/DNase。蛇毒→5'-核苷酸,牛脾→3'-核苷酸。", "kp": "nucleic_s0_2"}, {"id": "nucleic_mcq_2", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "蛇毒磷酸二酯酶水解核酸的产物是什么？", "o": ["A. 3'-核苷酸", "B. 5'-核苷酸", "C. 核苷+Pi", "D. 碱基+戊糖"], "a": "B", "e": "蛇毒磷酸二酯酶→5'-核苷酸。牛脾磷酸二酯酶→3'-核苷酸。两者都是核酸外切酶。", "kp": "nucleic_s0_2"}, {"id": "nucleic_mcq_3", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "嘌呤碱基分解代谢的终产物是什么？", "o": ["A. 尿素", "B. 尿酸", "C. β-丙氨酸", "D. 氨"], "a": "B", "e": "嘌呤(腺嘌呤/鸟嘌呤)→黄嘌呤→黄嘌呤氧化酶→尿酸。尿酸水溶性低→积累致痛风。", "kp": "nucleic_s0_1"}, {"id": "nucleic_mcq_4", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "嘧啶碱基分解代谢的终产物是什么？", "o": ["A. 尿酸", "B. β-丙氨酸/β-氨基异丁酸+NH3+CO2", "C. 尿素", "D. 乙酰CoA"], "a": "B", "e": "胞嘧啶/尿嘧啶→β-丙氨酸；胸腺嘧啶→β-氨基异丁酸。均为水溶性开环产物,易排出。", "kp": "nucleic_s0_1"}, {"id": "nucleic_mcq_5", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "催化次黄嘌呤→黄嘌呤→尿酸的酶是什么？", "o": ["A. 腺苷脱氨酶", "B. 黄嘌呤氧化酶", "C. 鸟嘌呤脱氨酶", "D. 核苷磷酸化酶"], "a": "B", "e": "黄嘌呤氧化酶(含FAD/Mo/铁硫簇)催化最后两步氧化→尿酸。别嘌呤醇抑制此酶→治疗痛风。", "kp": "nucleic_s0_5"}, {"id": "nucleic_mcq_6", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "痛风症的病因是什么？", "o": ["A. 尿酸酶过多", "B. 尿酸过多积累形成结晶沉积关节", "C. 嘌呤合成不足", "D. 嘧啶积累"], "a": "B", "e": "尿酸水溶性低→过饱和→尿酸钠结晶→关节沉积→炎症疼痛。治疗：别嘌呤醇。", "kp": "nucleic_s0_7"}, {"id": "nucleic_mcq_7", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "别嘌呤醇治疗痛风的机制是什么？", "o": ["A. 促进尿酸排出", "B. 抑制黄嘌呤氧化酶→减少尿酸生成", "C. 抑制嘌呤合成", "D. 促进嘌呤分解"], "a": "B", "e": "别嘌呤醇是黄嘌呤氧化酶竞争性抑制剂→且本身被氧化为别黄嘌呤(更强抑制剂)→阻断尿酸生成。", "kp": "nucleic_s0_7"}, {"id": "nucleic_mcq_8", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "嘌呤环中N1原子来自哪个前体？", "o": ["A. 甘氨酸", "B. 天冬氨酸", "C. 谷氨酰胺", "D. CO2"], "a": "B", "e": "嘌呤环：N1→Asp；N3/N9→Gln；N7+C4+C5→Gly；C6→CO2；C2/C8→N10-甲酰FH4。", "kp": "nucleic_s0_5"}], "judge": [], "fill": [{"id": "nucleic_fill_1", "modI": 0, "q": "嘌呤碱基分解的终产物是________,嘧啶碱基(胞嘧啶/尿嘧啶)分解的终产物是________,胸腺嘧啶分解的终产物是________。", "a": "尿酸,β-丙氨酸,β-氨基异丁酸", "kp": "nucleic_s0_5"}, {"id": "nucleic_fill_5", "modI": 0, "q": "痛风症的常用治疗药物是________,它抑制________酶。Lesch-Nyhan综合症是________酶缺陷导致。", "a": "别嘌呤醇,黄嘌呤氧化酶,HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)", "kp": "nucleic_s0_7"}, {"id": "nucleic_fill_11", "modI": 0, "q": "人类和灵长类缺乏________酶,故嘌呤分解终产物是________,而其他哺乳动物可进一步氧化为________。", "a": "尿酸酶(尿酸氧化酶),尿酸,尿囊素(allantoin)", "kp": "nucleic_s0_6"}], "short": [{"id": "nucleic_short_6", "modI": 0, "q": "简述嘌呤核苷酸分解代谢的全过程和痛风症的生化基础及治疗。", "a": "【嘌呤分解过程】\u000b①核苷酸水平:AMP→IMP;GMP→XMP\u000b②核苷水平:腺苷→次黄苷;鸟苷→黄苷\u000b③碱基水平:腺嘌呤→次黄嘌呤;鸟嘌呤→黄嘌呤\u000b④最终:次黄嘌呤/黄嘌呤→黄嘌呤氧化酶→尿酸\u000b\u000b关键酶:\u000b• 腺苷脱氨酶、腺嘌呤脱氨酶(先脱氨)\u000b• 黄嘌呤氧化酶(含FAD/Mo)→催化最后两步氧化\u000b\u000b【痛风症生化基础】\u000b• 尿酸水溶性极低→血中过饱和→尿酸钠结晶\u000b• 结晶沉积关节/肾脏→炎症反应→剧烈疼痛\u000b• 原因:嘌呤代谢亢进/尿酸排出障碍/遗传酶缺陷\u000b\u000b【治疗】\u000b• 别嘌呤醇:抑制黄嘌呤氧化酶→减少尿酸生成\u000b• 促尿酸排泄药:丙磺舒\u000b• 饮食控制:低嘌呤食物", "kp": "nucleic_s0_0"}], "calc": [], "term": [{"id": "nucleic_term_1", "modI": 0, "term": "核酸酶(Nuclease)", "def": "①催化核酸磷酸二酯键水解的酶类（定义）。②按底物分类：核糖核酸酶(RNase)作用于RNA、脱氧核糖核酸酶(DNase)作用于DNA（底物分类）。③按作用位点：核酸内切酶(切分子内部)、核酸外切酶(从末端逐个水解)（位点分类）。④举例：蛇毒磷酸二酯酶→5'-核苷酸、牛脾磷酸二酯酶→3'-核苷酸、限制性核酸内切酶EcoRⅠ识别特定序列（举例）。⑤生理意义：参与核酸降解、基因工程(限制酶)、DNA修复等（意义）。", "kps": "①定义(1分)②底物分类(1分)③位点分类(1分)④举例(1分)⑤意义(1分)", "kp": "nucleic_s0_2"}, {"id": "nucleic_term_3", "modI": 0, "term": "尿酸(Uric Acid)", "def": "①嘌呤碱基(腺嘌呤、鸟嘌呤)分解代谢的最终产物（定义）。②结构：嘌呤环2,6,8位氧化的三羟基嘌呤（结构）。③生成：次黄嘌呤/黄嘌呤经黄嘌呤氧化酶氧化生成（生成）。④特点：水溶性极低→易过饱和结晶（特点）。⑤病理：尿酸过多→尿酸钠结晶沉积关节→痛风症；HGPRT缺陷→Lesch-Nyhan综合症可致尿酸过多（病理）。", "kps": "①定义(1分)②结构(1分)③生成(1分)④水溶性低(1分)⑤痛风病理(1分)", "kp": "nucleic_s0_5"}, {"id": "nucleic_term_4", "modI": 0, "term": "黄嘌呤氧化酶(Xanthine Oxidase)", "def": "①催化次黄嘌呤→黄嘌呤→尿酸两步氧化反应的酶（定义）。②辅基：含FAD、钼(Mo)、铁-硫簇(Fe-S)（辅基）。③产物：每步氧化产生H2O2副产物（产物）。④意义：是嘌呤分解代谢终末限速酶，决定尿酸生成速率（意义）。⑤抑制：别嘌呤醇(竞争性抑制)用于治疗痛风（临床）。", "kps": "①定义(1分)②FAD/Mo/FeS(1分)③H2O2(1分)④限速酶意义(1分)⑤别嘌呤醇(1分)", "kp": "nucleic_s0_6"}, {"id": "nucleic_term_5", "modI": 0, "term": "痛风症(Gout)", "def": "①因尿酸在体内过多积累导致尿酸钠结晶沉积关节、肾脏等处的代谢性疾病（定义）。②生化基础：嘌呤代谢亢进、尿酸排泄障碍或相关酶缺陷(HGPRT/PRPP合成酶)（病因）。③症状：关节剧痛(常在脚拇趾)、炎症、尿酸性肾结石（症状）。④治疗：别嘌呤醇(抑制黄嘌呤氧化酶减少尿酸生成)、丙磺舒(促尿酸排泄)（治疗）。⑤预防：低嘌呤饮食、多饮水（预防）。", "kps": "①定义(1分)②生化基础(1分)③症状(1分)④治疗(1分)⑤预防(1分)", "kp": "nucleic_s0_7"}, {"id": "nucleic_term_16", "modI": 0, "term": "β-丙氨酸/β-氨基异丁酸", "def": "①嘧啶碱基分解代谢的最终产物（定义）。②胞嘧啶/尿嘧啶→β-丙氨酸；胸腺嘧啶→β-氨基异丁酸（产物）。③特点：水溶性开环氨基酸类，可直接排出或进一步代谢（特点）。④去向：β-丙氨酸→转氨→乙酰CoA→TCA；β-氨基异丁酸→转氨→琥珀酰CoA→TCA（去向）。⑤与嘌呤的区别：嘧啶分解不产生尿酸(水溶性好、易排出)（区别）。", "kps": "①定义(1分)②两种产物(1分)③特点(1分)④去向(1分)⑤与嘌呤区别(1分)", "kp": "nucleic_s0_1"}, {"id": "nucleic_term_21", "modI": 0, "term": "尿酸酶(Urate Oxidase/Uricase)", "def": "①催化尿酸氧化为尿囊素(allantoin)的酶（定义）。②反应：尿酸+O2+H2O→尿囊素+CO2+H2O2（反应）。③产物：尿囊素水溶性远高于尿酸→易排出（产物）。④分布：多数哺乳动物、两栖类有；人类和灵长类、鸟类、爬行类在进化中丢失此酶基因(假基因化)（分布）。⑤意义：人缺乏尿酸酶→尿酸是嘌呤代谢终产物→水溶性低→易结晶→痛风（意义）。", "kps": "①定义(1分)②反应(1分)③尿囊素更水溶(1分)④人/灵长类缺乏(1分)⑤痛风联系(1分)", "kp": "nucleic_s0_2"}]}, {"i": 1, "name": "模块二：嘌呤/嘧啶从头合成", "slides": [{"i": 0, "sec": "核酸代谢", "title": "Elion和Hitchings (p11-p13) (p1)", "notes": "Gertrude Elion和George Hitchings：1945年起合作→揭示正常细胞/癌细胞/原生动物/细菌/病毒在核酸代谢上的差异→开创了抗代谢物药物设计。\u000b1988年获诺贝尔生理学或医学奖(与James Black共享)——药物作用重要原理的发现。\u000b6-MP/别嘌呤醇/阿昔洛韦等源于其研究。", "page": 1, "level": "了解", "img": "assets/img/nucleic/p001.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "核酸代谢", "title": "嘧啶的分解-胞嘧啶/尿嘧啶 (p14)", "notes": "2.嘧啶分解(还原途径)：胞嘧啶→脱氨酶→尿嘧啶→二氢尿嘧啶脱氢酶(NADPH)→二氢尿嘧啶→水解→β-脲基丙酸→水解→β-丙氨酸+NH3+CO2。\u000bβ-丙氨酸→转氨→乙酰CoA(可进入代谢)。\u000b胞嘧啶先脱氨为尿嘧啶再还原。", "page": 14, "level": "掌握", "img": "assets/img/nucleic/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "核酸代谢", "title": "嘧啶分解-胸腺嘧啶 (p15)", "notes": "胸腺嘧啶分解：T→二氢胸腺嘧啶脱氢酶(NADPH)→二氢T→水解→β-脲基异丁酸→水解→β-氨基异丁酸+NH3+CO2。\u000bβ-氨基异丁酸→转氨→琥珀酰CoA(进入TCA)。\u000b注意：嘧啶分解终产物为开环β-氨基酸类(嘌呤→尿酸不同),更易排出。", "page": 15, "level": "掌握", "img": "assets/img/nucleic/p015.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "核酸代谢", "title": "第二节-合成代谢总览 (p16-p17) (p4)", "notes": "第二节 核苷酸的合成代谢。\u000b两条路线：①从头合成(de novo)→核糖磷酸+氨基酸+CO2+NH3→核苷酸。\u000b②补救途径(salvage)→碱基+PRPP或核苷→核苷酸。\u000b核苷酸→RNA；\u000b核糖核苷酸→脱氧核糖核苷酸→DNA。\u000bAMP/ADP/ATP是辅酶(NAD/NADP/FAD/CoA)的前体。", "page": 4, "level": "掌握", "img": "assets/img/nucleic/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "核酸代谢", "title": "嘌呤从头合成-原子来源 (p18-p19) (p5)", "notes": "一、嘌呤核苷酸的从头合成。\u000b嘌呤环原子来源：C6→CO2；\u000bN7+C4+C5→甘氨酸(Gly)；\u000bN1→天冬氨酸(Asp)；\u000bC2+C8→N10-甲酰FH4(一碳单位)；\u000bN3+N9→谷氨酰胺(Gln)。\u000b合成起点：PRPP(5-磷酸核糖焦磷酸)→IMP→AMP/GMP。\u000b口诀：Gly给C4C5N7,Asp给N1,Gln给N3N9,CO2给C6,甲酰FH4给C2C8。", "page": 5, "level": "掌握", "img": "assets/img/nucleic/p005.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "核酸代谢", "title": "嘌呤合成第一步-PRPP (p19-p20) (p6)", "notes": "起始反应：5-磷酸核糖+ATP→PRPP合成酶(磷酸核糖焦磷酸激酶)→PRPP+AMP(受嘌呤/嘧啶核苷酸反馈抑制)。\u000bPRPP+Gln→转酰胺酶→核糖胺-5-磷酸(PRA)。\u000bPRA+Gly→合成酶→甘氨酰胺核苷酸(GAR)。\u000bGAR+N10-CHO-FH4→转甲酰基酶→甲酰甘氨酰胺核苷酸(FGAR)。", "page": 6, "level": "掌握", "img": "assets/img/nucleic/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "核酸代谢", "title": "咪唑环的合成 (p21)", "notes": "FGAR→(Gln)→甲酰甘氨脒核苷酸(FGAM)→环化→5-氨基咪唑核苷酸(AIR)。\u000bAIR+CO2→羧化酶→5-氨基咪唑-4-羧酸核苷酸。\u000b再+Asp→合成酶→5-氨基咪唑-4-(N-琥珀基)氨甲酰核苷酸(SAICAR)。\u000b逐步构建嘌呤咪唑环。", "page": 21, "level": "理解", "img": "assets/img/nucleic/p021.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "核酸代谢", "title": "IMP的合成 (p22)", "notes": "SAICAR→裂解酶→释放延胡索酸→5-氨基咪唑-4-氨甲酰核苷酸(AICAR)→+N10-CHO-FH4→转甲酰基酶→5-甲酰胺基咪唑-4-氨甲酰核苷酸(FAICAR)→环化(合酶)→次黄苷酸(IMP)。\u000bIMP是嘌呤合成的第一个完整核苷酸(母体核苷酸)。", "page": 22, "level": "掌握", "img": "assets/img/nucleic/p022.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "nucleic_mcq_9", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤环中C2和C8原子来自什么？", "o": ["A. 甘氨酸", "B. 一碳单位(N10-CHO-FH4)", "C. CO2", "D. 天冬氨酸"], "a": "B", "e": "C2+C8→N10-甲酰FH4(一碳单位)。Gly给C4/C5/N7,Asp给N1,Gln给N3/N9,CO2给C6。", "kp": "nucleic_s1_4"}, {"id": "nucleic_mcq_10", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤从头合成的直接前体是什么？", "o": ["A. 葡萄糖", "B. PRPP(5-磷酸核糖焦磷酸)", "C. 核糖", "D. 脱氧核糖"], "a": "B", "e": "PRPP是嘌呤从头合成起点。由5-磷酸核糖+ATP经PRPP合成酶生成。", "kp": "nucleic_s1_4"}, {"id": "nucleic_mcq_11", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤从头合成的第一个完整核苷酸产物是什么？", "o": ["A. AMP", "B. GMP", "C. IMP(次黄苷酸)", "D. XMP"], "a": "C", "e": "IMP(次黄苷酸)是母体核苷酸→再分支生成AMP和GMP。", "kp": "nucleic_s1_4"}, {"id": "nucleic_mcq_12", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "IMP→AMP需要什么？", "o": ["A. Asp+GTP", "B. Gln+ATP", "C. NAD+", "D. 一碳单位"], "a": "A", "e": "IMP+Asp+GTP→腺苷酸代琥珀酸→AMP+延胡索酸。IMP→GMP需NAD++Gln+ATP。", "kp": "nucleic_s1_7"}, {"id": "nucleic_mcq_13", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤合成中由IMP→GMP需要哪两个酶？", "o": ["A. IMP脱氢酶+GMP合成酶", "B. 腺苷酸合成酶", "C. 脱氨酶", "D. 磷酸化酶"], "a": "A", "e": "IMP+NAD+→IMP脱氢酶→XMP→GMP合成酶(Gln+ATP)→GMP。", "kp": "nucleic_s1_7"}, {"id": "nucleic_mcq_14", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "6-巯基嘌呤(6-MP)的抗癌机制是什么？", "o": ["A. 抑制黄嘌呤氧化酶", "B. 嘌呤类似物,抑制IMP参与的反应", "C. 抑制嘧啶合成", "D. 抑制DHFR"], "a": "B", "e": "6-MP是嘌呤类似物→抑制IMP及后续反应→阻断嘌呤/核酸合成→用于白血病等抗癌治疗。", "kp": "nucleic_s1_7"}, {"id": "nucleic_mcq_15", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "氨甲喋呤(MTX)的作用机制是什么？", "o": ["A. 抑制黄嘌呤氧化酶", "B. 与二氢叶酸还原酶不可逆结合→抑制FH4", "C. 抑制胸苷酸合成酶", "D. 抑制Asp转氨甲酰酶"], "a": "B", "e": "MTX(叶酸类似物)→不可逆抑制DHFR→FH4不能再生→一碳单位转移受阻→嘌呤/胸苷酸合成受阻→抗癌。", "kp": "nucleic_s1_0"}, {"id": "nucleic_mcq_16", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘧啶环中C4、C5、C6原子来自什么？", "o": ["A. 甘氨酸", "B. 天冬氨酸(完整提供)", "C. 谷氨酰胺", "D. CO2"], "a": "B", "e": "嘧啶环：Asp完整提供C4/C5/C6；N1→Gln；C2→CO2；N3→Asp。", "kp": "nucleic_s1_4"}], "judge": [], "fill": [{"id": "nucleic_fill_2", "modI": 1, "q": "嘌呤环中N1来自________,N3和N9来自________,C2和C8来自________,C6来自________。", "a": "天冬氨酸(Asp),谷氨酰胺(Gln),N10-甲酰FH4(一碳单位),CO2", "kp": "nucleic_s1_4"}], "short": [{"id": "nucleic_short_1", "modI": 1, "q": "简述嘌呤核苷酸从头合成的全过程,标明嘌呤环各原子的来源。", "a": "嘌呤从头合成部位：肝(主要)。过程分两个阶段。\u000b\u000b【第一阶段:IMP合成】\u000b①5-P核糖+ATP→PRPP(PRPP合成酶)\u000b②PRPP+Gln→PRA(转酰胺酶,限速反应)\u000b③PRA+Gly→GAR(Gly提供C4C5N7)\u000b④GAR+N10-CHO-FH4→FGAR(提供C8)\u000b⑤FGAR+Gln→FGAM(提供N3)\u000b⑥环化→AIR(咪唑环闭合)\u000b⑦AIR+CO2→CAIR(提供C6)\u000b⑧CAIR+Asp→SAICAR(提供N1)\u000b⑨SAICAR→AICAR(裂解出延胡索酸)\u000b⑩AICAR+N10-CHO-FH4→FAICAR(提供C2)\u000b⑪FAICAR→IMP(环化)\u000b\u000b【第二阶段:IMP→AMP/GMP】\u000b• IMP+Asp+GTP→腺苷酸代琥珀酸→AMP\u000b• IMP+NAD+→XMP→GMP(Gln+ATP)\u000b\u000b嘌呤环原子来源:\u000bN1→Asp;N3/N9→Gln;N7+C4+C5→Gly;C6→CO2;C2/C8→一碳单位", "kp": "nucleic_s1_4"}, {"id": "nucleic_short_2", "modI": 1, "q": "比较嘌呤和嘧啶核苷酸从头合成的异同。", "a": "相同点:\u000b①都以PRPP为核糖磷酸供体\u000b②都需氨基酸(Gln/Asp)、CO2、一碳单位等前体\u000b③都是能量消耗大的合成过程\u000b\u000b不同点:\u000b①环构建顺序:嘌呤→先在PRPP上逐步构建嘌呤环→IMP;嘧啶→先合成完整嘧啶环(乳清酸)→再与PRPP结合→UMP\u000b②原子来源:嘌呤N1→Asp,C2/C8→一碳单位;嘧啶C4C5C6→Asp完整提供\u000b③首个产物:嘌呤→IMP;嘧啶→UMP\u000b④关键调控酶:嘌呤→PRPP转酰胺酶/PRPP合成酶;嘧啶→ATCase(受CTP反馈抑制)\u000b⑤部位:嘌呤主要在肝;嘧啶在多种组织", "kp": "nucleic_s1_4"}, {"id": "nucleic_short_7", "modI": 1, "q": "简述嘧啶核苷酸分解代谢的途径。", "a": "嘧啶分解经还原途径(先还原后开环):\u000b\u000b【胞嘧啶/尿嘧啶途径】\u000b①胞嘧啶→脱氨酶→尿嘧啶(先脱氨)\u000b②尿嘧啶+NADPH→二氢尿嘧啶脱氢酶→二氢尿嘧啶\u000b③二氢尿嘧啶+H2O→β-脲基丙酸\u000b④β-脲基丙酸+H2O→β-丙氨酸+NH3+CO2\u000b⑤β-丙氨酸→转氨→丙二酸半醛→乙酰CoA\u000b\u000b【胸腺嘧啶途径】\u000b①T+NADPH→二氢T→β-脲基异丁酸\u000b②β-脲基异丁酸→β-氨基异丁酸+NH3+CO2\u000b③β-氨基异丁酸→转氨→琥珀酰CoA\u000b\u000b特点:\u000b①先还原(需NADPH)后水解开环\u000b②终产物为水溶性β-氨基酸类(易排出,不沉淀)\u000b③与嘌呤不同:嘧啶分解不产生尿酸", "kp": "nucleic_s1_1"}], "calc": [], "term": [{"id": "nucleic_term_2", "modI": 1, "term": "限制性核酸内切酶(Restriction Endonuclease)", "def": "①能识别DNA特定碱基序列并在特定位点切割DNA的核酸内切酶（定义）。②识别序列多为4-8bp回文结构，如EcoRⅠ识别GAATTC（识别）。③切割方式：产生粘性末端或平末端（切割）。④来源：细菌中防御外源DNA(噬菌体)的天然免疫系统（来源）。⑤应用：基因工程的分子剪刀——DNA重组、分子克隆、基因图谱构建的核心工具（应用）。", "kps": "①定义(1分)②回文序列(1分)③粘性/平末端(1分)④细菌防御来源(1分)⑤基因工程应用(1分)", "kp": "nucleic_s1_0"}, {"id": "nucleic_term_6", "modI": 1, "term": "PRPP(5-磷酸核糖焦磷酸)", "def": "①5-磷酸核糖焦磷酸，核苷酸合成的关键中间物（定义）。②合成：5-磷酸核糖+ATP经PRPP合成酶(磷酸核糖焦磷酸激酶)生成（合成）。③功能：嘌呤从头合成、嘧啶从头合成和补救途径的共同核糖磷酸供体（功能）。④调控：PRPP合成酶受嘌呤/嘧啶核苷酸反馈抑制（调控）。⑤重要性：PRPP浓度是核苷酸合成速率的决定因素之一（重要性）。", "kps": "①定义(1分)②合成(1分)③三途径共同前体(1分)④反馈抑制(1分)⑤重要性(1分)", "kp": "nucleic_s1_5"}, {"id": "nucleic_term_7", "modI": 1, "term": "从头合成(De Novo Synthesis)", "def": "①以简单前体(氨基酸、CO2、NH3、核糖磷酸、一碳单位)为原料合成核苷酸的途径（定义）。②原料：嘌呤环由Gly/Asp/Gln/CO2/一碳单位构成；嘧啶环由Asp/Gln/CO2构成（原料）。③特点：耗能大、需多种酶、受严格反馈调控（特点）。④与补救途径的区别：从头合成利用简单前体从头构建，补救途径利用现成碱基/核苷（区别）。⑤主要部位：肝脏（嘌呤）；多种组织（嘧啶）（部位）。", "kps": "①定义(1分)②原料(1分)③特点(1分)④与补救区别(1分)⑤部位(1分)", "kp": "nucleic_s1_4"}, {"id": "nucleic_term_20", "modI": 1, "term": "氨甲酰磷酸合成酶II(CPS-II)", "def": "①嘧啶合成中催化Gln+CO2+2ATP→氨甲酰磷酸的酶（定义）。②部位：细胞质(与尿素循环的CPS-I在线粒体不同)（部位）。③氮源：利用Gln酰胺氮(CPS-I利用NH3)（氮源）。④调控：受UMP反馈抑制（调控）。⑤意义：嘧啶合成的限速步骤之一，为嘧啶环提供氨甲酰基（意义）。", "kps": "①定义(1分)②细胞质(1分)③Gln氮源(1分)④UMP抑制(1分)⑤意义(1分)", "kp": "nucleic_s1_6"}]}, {"i": 2, "name": "模块三：脱氧核苷酸/补救合成", "slides": [{"i": 0, "sec": "核酸代谢", "title": "IMP→AMP/GMP (p23)", "notes": "IMP转化：①→AMP：IMP+Asp+GTP→腺苷酸代琥珀酸合成酶→腺苷酸代琥珀酸→裂解酶→AMP+延胡索酸。\u000b②→GMP：IMP+NAD+→IMP脱氢酶→黄苷酸(XMP)→+Gln+ATP→GMP合成酶→GMP。\u000bAMP与GMP相互调控：ATP反馈抑IMP→AMP支路；\u000bGTP反馈抑IMP→GMP支路。", "page": 23, "level": "掌握", "img": "assets/img/nucleic/p023.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "核酸代谢", "title": "嘌呤合成抗代谢物 (p24)", "notes": "(二)嘌呤合成抗代谢物。\u000b1.嘌呤类似物：6-巯基嘌呤(6-MP)→抑制IMP参与的反应。\u000b2.Gln类似物：重氮丝氨酸、6-重氮-5-氧-正亮氨酸→抑制Gln参与的反应。\u000b这些药物抑制嘌呤→抑制核酸合成→用于抗癌治疗。\u000b6-MP是急性淋巴细胞白血病(ALL)的经典药物。", "page": 24, "level": "掌握", "img": "assets/img/nucleic/p024.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "核酸代谢", "title": "Asp和叶酸类似物 (p25)", "notes": "3.Asp类似物：羽田杀菌素(hadacidin)→抑制Asp参与的反应(嘌呤/嘧啶合成)。\u000b4.叶酸类似物：氨基喋呤、氨甲喋呤(MTX)→与二氢叶酸还原酶(DHFR)不可逆结合→抑制FH4再生→阻断一碳单位转移→阻断嘌呤/胸苷酸合成。\u000bMTX是广谱抗癌/抗风湿药。", "page": 25, "level": "掌握", "img": "assets/img/nucleic/p025.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "核酸代谢", "title": "嘧啶从头合成-原子来源 (p26-p27) (p4)", "notes": "二、嘧啶核苷酸的从头合成。\u000b嘧啶环原子来源：N1→Gln；\u000bC2→CO2；\u000bN3→Asp；\u000bC4/C5/C6→Asp(完整贡献C4C5C6)。\u000b与嘌呤不同：嘧啶先合成嘧啶环(乳清酸)→再与PRPP结合。\u000b合成产物UMP→UDP→UTP→CTP(经CTP合成酶)。", "page": 4, "level": "掌握", "img": "assets/img/nucleic/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "核酸代谢", "title": "嘧啶合成途径 (p28)", "notes": "嘧啶合成关键步骤：Gln+CO2+2ATP+H2O→氨甲酰磷酸合成酶II(CPS-II,细胞质)→氨甲酰磷酸+2ADP+Pi+Glu。\u000b氨甲酰磷酸+Asp→Asp转氨甲酰酶(ATCase)→氨甲酰Asp→二氢乳清酸酶→二氢乳清酸→二氢乳清酸脱氢酶→乳清酸。\u000bATCase是嘧啶合成关键调控酶(受CTP反馈抑制)。", "page": 28, "level": "掌握", "img": "assets/img/nucleic/p028.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "核酸代谢", "title": "乳清酸→UMP→CTP (p29)", "notes": "乳清酸+PRPP→乳清苷酸转移酶→乳清苷酸(OMP)→脱羧酶→UMP。\u000bUMP→UMP激酶→UDP→核苷二磷酸激酶→UTP→CTP合成酶(Gln+ATP)→CTP。\u000b注意：嘧啶环先于PRPP组装完成后→再连接→与嘌呤(先PRPP后建环)相反。", "page": 29, "level": "掌握", "img": "assets/img/nucleic/p029.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "核酸代谢", "title": "脱氧核苷酸合成-核糖核苷酸还原 (p30)", "notes": "三、脱氧核苷酸的合成。\u000b1.核糖核苷酸还原：NDP(核糖)→核苷二磷酸还原酶(核糖核苷酸还原酶)→dNDP。\u000b还原剂：硫氧还蛋白(SH)2→氧化为S-S；\u000b再生需硫氧还蛋白还原酶+NADPH。\u000b底物为NDP(不是NMP/NTP)。\u000b需Mg2+。\u000b生成dADP/dGDP/dCDP/dUDP。", "page": 30, "level": "掌握", "img": "assets/img/nucleic/p030.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "nucleic_mcq_17", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "嘧啶从头合成与嘌呤从头合成的关键区别是什么？", "o": ["A. 完全无区别", "B. 嘧啶先合成嘧啶环再连PRPP,嘌呤先PRPP后建环", "C. 嘌呤先成环", "D. 两者都不需PRPP"], "a": "B", "e": "嘧啶：先合成乳清酸(完整嘧啶环)→再+PRPP→OMP→UMP。嘌呤：先PRPP→逐步在PRPP上构建嘌呤环→IMP。", "kp": "nucleic_s2_3"}, {"id": "nucleic_mcq_18", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "嘧啶合成中关键调控酶是什么？", "o": ["A. 氨甲酰磷酸合成酶II(CPS-II)", "B. 天冬氨酸转氨甲酰酶(ATCase)", "C. 乳清酸脱羧酶", "D. UMP激酶"], "a": "B", "e": "ATCase是嘧啶合成关键调控酶→受CTP反馈抑制→控制嘧啶合成速率。", "kp": "nucleic_s2_4"}, {"id": "nucleic_mcq_19", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "CTP由哪个核苷酸转变而来？", "o": ["A. UMP", "B. UTP→CTP合成酶(Gln)", "C. 直接合成", "D. dCMP"], "a": "B", "e": "UMP→UDP→UTP→CTP合成酶(Gln+ATP)→CTP。", "kp": "nucleic_s2_5"}, {"id": "nucleic_mcq_20", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "核糖核苷酸还原的底物是什么？", "o": ["A. NMP", "B. NDP(二磷酸核糖核苷)", "C. NTP", "D. 碱基"], "a": "B", "e": "核糖核苷酸还原酶作用于NDP(ADP/GDP/CDP/UDP)→dNDP。还原剂硫氧还蛋白+NADPH。", "kp": "nucleic_s2_6"}, {"id": "nucleic_mcq_21", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "dTMP合成的直接前体和甲基供体是什么？", "o": ["A. dCMP+SAM", "B. dUMP+N5,N10-CH2-FH4", "C. dUDP+FH4", "D. T+PRPP"], "a": "B", "e": "dUMP+胸苷酸合成酶(N5,N10-CH2-FH4供甲基)→dTMP+FH2。FH2→DHFR→FH4再生。5-FU抑制此酶。", "kp": "nucleic_s2_0"}, {"id": "nucleic_mcq_22", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "5-氟尿嘧啶(5-FU)的抗癌机制是什么？", "o": ["A. 抑制黄嘌呤氧化酶", "B. 转成5-FdUMP→抑制胸苷酸合成酶", "C. 抑制DHFR", "D. 抑制ATCase"], "a": "B", "e": "5-FU在体内→5-FdUMP→与胸苷酸合成酶不可逆结合→阻断dTMP合成→DNA合成受阻→抗癌。", "kp": "nucleic_s2_3"}, {"id": "nucleic_mcq_23", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "嘌呤补救途径中,AMP和GMP合成以哪条为主？", "o": ["A. 核苷磷酸化酶途径", "B. 磷酸核糖转移酶途径(碱基+PRPP)", "C. 核苷激酶途径", "D. 从头合成"], "a": "B", "e": "AMP/GMP/IMP补救合成以磷酸核糖转移酶(碱基+PRPP)为主；CMP/UMP/dTMP以核苷磷酸化酶+核苷激酶为主。", "kp": "nucleic_s2_0"}, {"id": "nucleic_mcq_24", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "Lesch-Nyhan综合症的分子病因是什么？", "o": ["A. APRT缺陷", "B. HGPRT缺陷", "C. 黄嘌呤氧化酶缺陷", "D. 腺苷脱氨酶缺陷"], "a": "B", "e": "HGPRT缺陷(X连锁隐性)→补救途径受阻→PRPP积累→从头合成亢进→尿酸过多→痛风+自残+神经损害。", "kp": "nucleic_s2_2"}], "judge": [], "fill": [{"id": "nucleic_fill_3", "modI": 2, "q": "嘌呤从头合成的直接前体是________,其第一个完整核苷酸产物是________,再由它分支生成________和________。", "a": "PRPP(5-磷酸核糖焦磷酸),IMP(次黄苷酸),AMP,GMP", "kp": "nucleic_s2_3"}, {"id": "nucleic_fill_4", "modI": 2, "q": "嘧啶环中N1来自________,C2来自________,C4/C5/C6完整来自________。嘧啶合成先形成________再与PRPP结合。", "a": "谷氨酰胺(Gln),CO2,天冬氨酸(Asp),乳清酸(嘧啶环)", "kp": "nucleic_s2_3"}, {"id": "nucleic_fill_8", "modI": 2, "q": "5-氟尿嘧啶(5-FU)转成________抑制________酶;氨甲喋呤抑制________酶;6-巯基嘌呤是________类似物。", "a": "5-FdUMP,胸苷酸合成酶,二氢叶酸还原酶(DHFR),嘌呤", "kp": "nucleic_s2_2"}], "short": [{"id": "nucleic_short_3", "modI": 2, "q": "简述嘧啶核苷酸从头合成途径,标明关键调控酶。", "a": "嘧啶从头合成(细胞质):\u000b\u000b【嘧啶环合成】\u000b①Gln+CO2+2ATP→氨甲酰磷酸(CPS-II)\u000b②氨甲酰磷酸+Asp→氨甲酰Asp(ATCase★关键调控酶)\u000b③氨甲酰Asp→二氢乳清酸(二氢乳清酸酶)\u000b④二氢乳清酸→乳清酸(二氢乳清酸脱氢酶)\u000b\u000b【连接PRPP】\u000b⑤乳清酸+PRPP→OMP(乳清苷酸转移酶)\u000b⑥OMP→UMP(脱羧酶)\u000b\u000b【磷酸化】\u000b⑦UMP→UDP→UTP\u000b⑧UTP+Gln→CTP(CTP合成酶)\u000b\u000b调控:\u000b★ATCase受CTP反馈抑制(别构)→嘧啶合成的关键调控点\u000bCPS-II受UMP反馈抑制\u000b\u000b注意:与嘌呤不同,嘧啶先成环后连PRPP", "kp": "nucleic_s2_3"}, {"id": "nucleic_short_5", "modI": 2, "q": "简述核糖核苷酸还原酶的作用机制和dTMP的合成过程。", "a": "【核糖核苷酸还原】\u000b• 底物:NDP(ADP/GDP/CDP/UDP)→dNDP\u000b• 酶:核糖核苷酸还原酶(含铁/酪氨酸自由基)\u000b• 还原剂:硫氧还蛋白(SH)2→氧化为S-S\u000b• 再生:硫氧还蛋白还原酶+NADPH\u000b• 产物dNDP→磷酸化→dNTP→DNA合成前体\u000b\u000b【dTMP合成】\u000b• dUMP+N5,N10-CH2-FH4→胸苷酸合成酶→dTMP+FH2\u000b• 甲基供体:N5,N10-亚甲基FH4(一碳单位)\u000b• FH2→二氢叶酸还原酶(DHFR)→FH4再生\u000b\u000bdUMP来源:\u000b①dCMP→脱氨酶→dUMP\u000b②dUDP→dUDP酶→dUMP\u000b\u000b药物靶点:\u000b5-FU→5-FdUMP→抑制胸苷酸合成酶(抗癌)\u000bMTX→抑制DHFR→阻断FH4再生(抗癌)", "kp": "nucleic_s2_6"}, {"id": "nucleic_short_9", "modI": 2, "q": "简述核苷酸合成的抗代谢物及其作用机制。", "a": "抗代谢物是结构与正常代谢物类似、能干扰代谢的药物:\u000b\u000b【嘌呤类似物】\u000b• 6-巯基嘌呤(6-MP)→抑制IMP参与的反应→抗癌\u000b• 8-氮杂鸟嘌呤\u000b\u000b【嘧啶类似物】\u000b• 5-氟尿嘧啶(5-FU)→5-FdUMP→抑制胸苷酸合成酶→抗癌\u000b• 5-碘脱氧尿苷(疱疹净)→抗病毒\u000b\u000b【Gln类似物】\u000b• 重氮丝氨酸、6-重氮-5-氧-正亮氨酸(DON)→抑制Gln参与的反应\u000b\u000b【Asp类似物】\u000b• 羽田杀菌素(hadacidin)→抑制Asp参与的反应\u000b\u000b【叶酸类似物】\u000b• 氨甲喋呤(MTX)、氨基喋呤→不可逆抑制DHFR→阻断FH4→抑制一碳单位转移→阻断嘌呤/胸苷酸合成→抗癌/抗风湿\u000b\u000b原理:利用正常细胞与癌细胞/病原体核酸代谢差异选择性杀伤", "kp": "nucleic_s2_1"}], "calc": [{"id": "nucleic_calc_1", "modI": 2, "q": "试分析6-巯基嘌呤(6-MP)和5-氟尿嘧啶(5-FU)进入体内可能的代谢途径和作用机制。", "a": "6-MP抑制嘌呤合成(IMP→AMP/GMP);5-FU抑制胸苷酸合成(dTMP)", "steps": "【6-巯基嘌呤(6-MP)】\u000b①结构类似次黄嘌呤(巯基取代6位OH)\u000b②进入体内→与PRPP结合(HGPRT)→6-MP核苷酸\u000b③6-MP核苷酸抑制IMP参与的反应:\u000b  • 抑制IMP→AMP(腺苷酸代琥珀酸合成酶)\u000b  • 抑制IMP→GMP(IMP脱氢酶)\u000b  • 反馈抑制PRPP合成\u000b④结果:嘌呤核苷酸↓→核酸合成↓→抑制癌细胞增殖\u000b\u000b【5-氟尿嘧啶(5-FU)】\u000b①结构类似尿嘧啶(F取代5位H)\u000b②进入体内→补救途径→5-FdUMP\u000b③5-FdUMP与胸苷酸合成酶不可逆结合\u000b④阻断dUMP→dTMP→dTTP不足→DNA合成受阻\u000b⑤也可掺入RNA→干扰功能\u000b\u000b共同点:都是抗代谢物→干扰核酸合成→抗癌\u000b区别:6-MP作用于嘌呤,5-FU作用于嘧啶(dTMP)", "kp": "nucleic_s2_1"}, {"id": "nucleic_calc_2", "modI": 2, "q": "计算从PRPP开始合成1分子AMP和1分子GMP各消耗多少高能磷酸键？", "a": "AMP约消耗6~P;GMP约消耗7~P(从PRPP起算)", "steps": "【从PRPP→IMP】(共同路径)\u000b①PRPP+Gln→PRA:消耗PRPP的焦磷酸键(1个~P)\u000b②PRA+Gly→GAR:消耗1ATP\u000b③GAR→FGAR→FGAM:消耗1ATP\u000b④后续到IMP:共约5个~P\u000b\u000b【IMP→AMP】\u000bIMP+Asp+GTP→腺苷酸代琥珀酸→AMP+延胡索酸\u000b消耗1GTP(1个~P)\u000b\u000b【IMP→GMP】\u000bIMP+NAD+→XMP(0)\u000bXMP+Gln+ATP→GMP:消耗1ATP(1个~P)\u000b\u000b总计(从5-P核糖算):\u000b5-P核糖→PRPP:1ATP\u000bPRPP→IMP:约4ATP\u000bIMP→AMP:1GTP;IMP→GMP:1ATP\u000bAMP:约6~P;GMP:约7~P\u000b\u000b注意:从头合成能耗大,补救途径节能(仅1个~P)→细胞优先补救", "kp": "nucleic_s2_0"}, {"id": "nucleic_calc_3", "modI": 2, "q": "论述嘌呤核苷酸从头合成的调控机制。", "a": "嘌呤从头合成受多级反馈调控,防止过量合成", "steps": "【第一级:PRPP合成酶】\u000b• 受嘌呤核苷酸(IMP/AMP/GMP)反馈抑制\u000b• 受ADP/AMP激活(能量信号)\u000b• PRPP是嘌呤/嘧啶/补救途径共同前体\u000b\u000b【第二级:PRPP转酰胺酶(限速酶)】\u000b• 受AMP/GMP反馈抑制\u000b• 受PRPP浓度调控\u000b\u000b【第三级:IMP分支调控】\u000b• AMP过多→反馈抑制IMP→AMP支路(腺苷酸代琥珀酸合成酶)\u000b• GMP过多→反馈抑制IMP→GMP支路(IMP脱氢酶)\u000b\u000b【交叉调节】\u000b• GTP是AMP合成所需(腺苷酸代琥珀酸合成酶用GTP)\u000b• ATP是GMP合成所需(GMP合成酶用ATP)\u000b• 高ATP→促进GMP生成;高GTP→促进AMP生成\u000b→维持嘌呤核苷酸池平衡\u000b\u000b意义:多级反馈调控→精确控制核苷酸合成→避免浪费/防止代谢紊乱", "kp": "nucleic_s2_3"}, {"id": "nucleic_calc_5", "modI": 2, "q": "计算嘧啶从头合成中,从氨甲酰磷酸到UMP各步骤消耗的高能磷酸键总数,并与嘌呤合成比较。", "a": "氨甲酰磷酸→UMP直接消耗0~P(但从头合计约3~P)", "steps": "嘧啶从头合成能耗:\u000b①Gln+CO2+2ATP→氨甲酰磷酸(CPS-II):消耗2~P\u000b②氨甲酰磷酸+Asp→氨甲酰Asp(ATCase):0\u000b③→二氢乳清酸→乳清酸:0(仅氧化还原)\u000b④乳清酸+PRPP→OMP:0(PRPP的~P已付)\u000b⑤OMP→UMP:0(脱羧)\u000b\u000b从氨甲酰磷酸→UMP直接消耗:0~P\u000b但从CO2/Gln/Asp→UMP:2~P(CPS-II的2ATP)\u000b\u000b若计入PRPP:\u000b5-P核糖→PRPP:1ATP\u000b\u000b总计(从头):\u000b嘧啶UMP:约3~P(CPS-II的2ATP+PRPP的1ATP)\u000b嘌呤IMP:约5~P\u000b\u000b比较:\u000b①嘌呤合成能耗>嘧啶(5~P vs 3~P)\u000b②嘧啶先合成环再连PRPP→更节省\u000b③CTP合成:UTP+Gln+ATP→CTP,再耗1~P", "kp": "nucleic_s2_3"}], "term": [{"id": "nucleic_term_11", "modI": 2, "term": "IMP(次黄苷酸)", "def": "①次黄苷酸，嘌呤核苷酸从头合成的第一个完整核苷酸产物（定义）。②结构：次黄嘌呤碱基+核糖+磷酸（结构）。③作用：作为嘌呤合成母体→分支生成AMP和GMP（作用）。④转化：IMP+Asp+GTP→AMP；IMP+NAD+→XMP→GMP（转化）。⑤意义：IMP是嘌呤从头合成与分支合成的分水岭，其浓度受严格调控（意义）。", "kps": "①定义(1分)②结构(1分)③母体作用(1分)④转化(1分)⑤分水岭意义(1分)", "kp": "nucleic_s2_0"}, {"id": "nucleic_term_12", "modI": 2, "term": "一碳单位(One-carbon Unit)", "def": "①某些氨基酸(甘氨酸、丝氨酸、组氨酸、甲硫氨酸)分解代谢产生的含一个碳原子的基团（定义）。②种类：甲基(-CH3)、亚甲基(-CH2-)、次甲基(-CH=)、甲酰基(-CHO)、亚氨甲基(-CH=NH)（种类）。③载体：四氢叶酸(FH4)、S-腺苷甲硫氨酸(SAM)（载体）。④来源：Ser、Gly、His、Met等（来源）。⑤作用：嘌呤合成(C2/C8来自N10-CHO-FH4)、胸苷酸合成(dTMP的甲基来自N5,N10-CH2-FH4)（作用）。", "kps": "①定义(1分)②种类(1分)③FH4/SAM载体(1分)④来源(1分)⑤嘌呤/dTMP合成(1分)", "kp": "nucleic_s2_2"}, {"id": "nucleic_term_13", "modI": 2, "term": "四氢叶酸(FH4)", "def": "①叶酸(维生素B9)的活性形式，一碳单位的重要载体（定义）。②结构：叶酸还原(二氢叶酸还原酶催化)→FH4（结构）。③作用：N5、N10或N5,N10位结合一碳单位→参与嘌呤、胸苷酸合成（作用）。④再生：FH2→二氢叶酸还原酶→FH4（再生）。⑤临床：叶酸类似物(MTX)抑制DHFR→阻断FH4→抑制核酸合成→抗癌；叶酸缺乏→巨幼红细胞性贫血（临床）。", "kps": "①定义(1分)②活性形式(1分)③一碳载体(1分)④DHFR再生(1分)⑤临床(1分)", "kp": "nucleic_s2_2"}, {"id": "nucleic_term_14", "modI": 2, "term": "二氢叶酸还原酶(DHFR)", "def": "①催化二氢叶酸(FH2)还原为四氢叶酸(FH4)的酶（定义）。②功能：再生FH4→维持一碳单位代谢→保证嘌呤和胸苷酸合成（功能）。③辅酶：NADPH（辅酶）。④抑制剂：氨甲喋呤(MTX)、氨基喋呤(叶酸类似物)→不可逆结合→抑制FH4再生（抑制）。⑤临床意义：DHFR是抗癌/抗细菌/抗疟疾药物的重要靶点（意义）。", "kps": "①定义(1分)②功能(1分)③NADPH(1分)④MTX抑制(1分)⑤药物靶点(1分)", "kp": "nucleic_s2_2"}, {"id": "nucleic_term_15", "modI": 2, "term": "抗代谢物(Antimetabolite)", "def": "①结构与天然代谢物类似、能竞争性干扰正常代谢过程的物质（定义）。②原理：冒充正常底物→抑制关键酶→阻断代谢途径（原理）。③分类：嘌呤类似物(6-MP)、嘧啶类似物(5-FU)、叶酸类似物(MTX)、氨基酸类似物(重氮丝氨酸、DON)（分类）。④应用：抗癌(抑制快速分裂细胞核酸合成)、抗病毒、抗菌（应用）。⑤代表：Elion和Hitchings因抗代谢物药物设计获1988年诺贝尔奖（代表）。", "kps": "①定义(1分)②原理(1分)③分类(1分)④应用(1分)⑤诺贝尔奖(1分)", "kp": "nucleic_s2_1"}, {"id": "nucleic_term_17", "modI": 2, "term": "核糖核苷酸还原酶(Ribonucleotide Reductase)", "def": "①催化核糖核苷酸(NDP)还原为脱氧核糖核苷酸(dNDP)的酶（定义）。②底物：NDP(二磷酸核糖核苷)，非NMP/NTP（底物）。③机制：含铁-硫簇和酪氨酸自由基，利用硫氧还蛋白作还原剂（机制）。④再生：硫氧还蛋白(SH)2→S-S，由硫氧还蛋白还原酶+NADPH再生（再生）。⑤意义：提供dNTP前体→DNA合成；受调控→保证脱氧核苷酸池平衡（意义）。", "kps": "①定义(1分)②底物NDP(1分)③机制(1分)④硫氧还蛋白再生(1分)⑤DNA前体意义(1分)", "kp": "nucleic_s2_6"}, {"id": "nucleic_term_18", "modI": 2, "term": "硫氧还蛋白(Thioredoxin)", "def": "①含-SH的氧化还原蛋白，作为核糖核苷酸还原酶的还原剂（定义）。②机制：硫氧还蛋白(SH)2被氧化为S-S形式，同时还原核糖核苷酸为脱氧核糖核苷酸（机制）。③再生：硫氧还蛋白还原酶+NADPH→还原S-S为(SH)2（再生）。④功能：维持细胞内还原环境，参与核苷酸还原等多种氧化还原反应（功能）。⑤意义：是连接NADPH与脱氧核苷酸合成的关键中间体（意义）。", "kps": "①定义(1分)②氧化还原机制(1分)③再生(1分)④功能(1分)⑤意义(1分)", "kp": "nucleic_s2_6"}, {"id": "nucleic_term_22", "modI": 2, "term": "乳清酸尿症(Orotic Aciduria)", "def": "①UMP合成酶缺陷导致的嘧啶核苷酸从头合成障碍的遗传病（定义）。②缺陷酶：UMP合成酶是双功能酶——含乳清酸磷酸核糖转移酶(OPRT)+乳清苷酸脱羧酶(OMP脱羧酶)两种活性（缺陷酶）。③机制：嘧啶从头合成受阻→乳清酸大量积累→尿中排出；嘧啶核苷酸不足→核酸合成障碍（机制）。④症状：巨幼红细胞性贫血(对叶酸/VB12治疗无效)、生长发育迟缓（症状）。⑤治疗：补充尿苷(经补救途径生成UMP,绕过缺陷步骤)（治疗）。", "kps": "①定义(1分)②UMP合成酶双功能(1分)③乳清酸积累(1分)④巨幼贫血(1分)⑤尿苷治疗(1分)", "kp": "nucleic_s2_5"}, {"id": "nucleic_term_24", "modI": 2, "term": "谷氧还蛋白(Glutaredoxin)", "def": "①含-SH的小分子氧化还原蛋白，作为核糖核苷酸还原酶的另一电子供体（定义）。②机制：谷氧还蛋白(SH)2被氧化为S-S，同时还原核糖核苷酸为脱氧核糖核苷酸（机制）。③电子来源：利用谷胱甘肽(GSH)作还原剂→与硫氧还蛋白(利用NADPH+硫氧还蛋白还原酶)并列的还原系统（电子来源）。④功能：与硫氧还蛋白共同维持核糖核苷酸还原酶的还原力供应（功能）。⑤意义：体现了细胞氧化还原系统的冗余性和灵活性（意义）。", "kps": "①定义(1分)②氧化还原机制(1分)③GSH电子来源(1分)④与硫氧还蛋白并列(1分)⑤意义(1分)", "kp": "nucleic_s2_6"}, {"id": "nucleic_term_25", "modI": 2, "term": "dUTPase(dUTP焦磷酸酶)", "def": "①催化dUTP水解为dUMP+PPi的酶（定义）。②作用一：降低dUTP浓度→防止dUTP代替dTTP掺入DNA(避免U:G错配、DNA损伤)（防错配作用）。③作用二：生成的dUMP是胸苷酸合成酶底物→dTMP合成前体（提供前体）。④重要性：dUTP/dTTP比值是DNA合成保真性的关键决定因素（重要性）。⑤联系：与胸苷酸合成酶、DHFR共同维持dTMP池→保证DNA合成所需dTTP（联系）。", "kps": "①定义(1分)②防dUTP掺入(2分)③提供dUMP(1分)④保真性意义(1分)⑤与dTMP合成联系(1分)", "kp": "nucleic_s2_5"}]}, {"i": 3, "name": "模块四：核苷酸与核酸代谢关系", "slides": [{"i": 0, "sec": "核酸代谢", "title": "胸苷酸(dTMP)的合成 (p31)", "notes": "2.胸苷酸合成：dUMP→胸苷酸合成酶(N5,N10-CH2-FH4提供甲基)→dTMP+FH2。\u000bFH2→二氢叶酸还原酶→FH4(再生)。\u000bdUMP来源：dUDP→dUDP酶→dUMP，或dCMP→脱氨酶→dUMP。\u000bdTMP是DNA特有碱基T的来源→是抗癌药靶点。", "page": 31, "level": "掌握", "img": "assets/img/nucleic/p031.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "核酸代谢", "title": "胸苷酸合成抑制剂 (p32)", "notes": "胸苷酸合成抑制剂：5-氟尿嘧啶(5-FU)→在体内转成5-FdUMP→不可逆抑制胸苷酸合成酶(抗癌)。\u000b5-碘脱氧尿苷(疱疹净/抗病毒)。\u000b叶酸类似物(氨甲喋呤)→抑制DHFR→阻断FH4→间接抑制dTMP合成。\u000b这些药物选择性作用于快速分裂细胞。", "page": 32, "level": "掌握", "img": "assets/img/nucleic/p032.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "核酸代谢", "title": "补救途径 (p33-p34) (p3)", "notes": "四、核苷酸的补救合成。\u000b两条途径：①核苷磷酸化酶：碱基+核糖-1-P→核苷→核苷激酶+ATP→核苷酸。\u000b②磷酸核糖转移酶：碱基+PRPP→核苷酸+PPi。\u000bAMP/GMP/IMP以②为主；\u000bCMP/UMP/dTMP以①为主。\u000b关键酶：腺嘌呤磷酸核糖转移酶(APRT)、次黄嘌呤-鸟嘌呤磷酸核糖转移酶(HGPRT)。", "page": 3, "level": "掌握", "img": "assets/img/nucleic/p003.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "核酸代谢", "title": "补救合成与Lesch-Nyhan综合症 (p34-p35) (p4)", "notes": "Lesch-Nyhan综合症：HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)遗传缺陷→补救途径受阻→PRPP积累→从头合成亢进→尿酸大量产生→痛风+自残+智力障碍(神经系统损害)。\u000bX连锁隐性遗传。\u000b说明补救途径重要性：脑组织几乎全靠补救途径合成核苷酸。", "page": 4, "level": "掌握", "img": "assets/img/nucleic/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "核酸代谢", "title": "核苷酸→核苷三磷酸 (p36)", "notes": "五、单核苷酸转化为核苷三磷酸。\u000bNMP+ATP→核苷一磷酸激酶→NDP+ADP；\u000bNDP+ATP→核苷二磷酸激酶→NTP+ADP。\u000b核苷二磷酸激酶底物广泛(可催化不同核苷酸)。\u000bNTP是RNA合成前体；\u000bdNTP是DNA合成前体。", "page": 36, "level": "掌握", "img": "assets/img/nucleic/p036.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "核酸代谢", "title": "核苷酸合成与核酸合成的关系 (p37)", "notes": "六、核苷酸合成与核酸合成的关系。\u000b总结图：IMP→AMP/GMP→ADP/GDP→ATP/GTP→RNA；\u000bUMP→UDP/UTP→CTP→RNA；\u000b核苷酸还原→dNTP→DNA。\u000bdUMP→dTMP→dTTP→DNA。\u000b展示嘌呤/嘧啶→核糖核苷酸→脱氧核苷酸→核酸的完整脉络。", "page": 37, "level": "掌握", "img": "assets/img/nucleic/p037.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "核酸代谢", "title": "四大物质代谢图 (p38)", "notes": "四大物质代谢全景图：糖/脂/蛋白质/核酸代谢互相联系。\u000b核酸代谢：核苷酸→戊糖-5-P→PPP；\u000b嘌呤分解→尿酸；\u000b嘧啶分解→β-丙氨酸→乙酰CoA/琥珀酰CoA→TCA。\u000b核苷酸合成前体(甘氨酸/Asp/Gln/CO2/一碳单位)来自氨基酸和糖代谢。", "page": 38, "level": "掌握", "img": "assets/img/nucleic/p038.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "nucleic_mcq_25", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "核苷二磷酸激酶的作用是什么？", "o": ["A. NMP→NDP", "B. NDP→NTP(底物广泛)", "C. 核苷→核苷酸", "D. 碱基→核苷"], "a": "B", "e": "核苷二磷酸激酶催化NDP+ATP→NTP+ADP,底物广泛。核苷一磷酸激酶催化NMP→NDP。", "kp": "nucleic_s3_4"}, {"id": "nucleic_mcq_26", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "嘧啶分解产生的β-丙氨酸最终去向？", "o": ["A. 直接排出", "B. 转氨→乙酰CoA(可进入代谢)", "C. 生成尿酸", "D. 生成尿素"], "a": "B", "e": "β-丙氨酸→转氨→丙二酸半醛→乙酰CoA。胸腺嘧啶→β-氨基异丁酸→琥珀酰CoA。", "kp": "nucleic_s3_6"}, {"id": "nucleic_mcq_27", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "嘌呤核苷酸从头合成的限速反应是什么？", "o": ["A. IMP→AMP", "B. PRPP+Gln→PRA(转酰胺酶)", "C. IMP→GMP", "D. 磷酸核糖焦磷酸激酶"], "a": "B", "e": "PRPP+Gln→PRA(5-磷酸核糖胺)是嘌呤从头合成第一个限速反应→受AMP/GMP反馈抑制。", "kp": "nucleic_s3_5"}, {"id": "nucleic_mcq_28", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "dCMP如何转变为dUMP？", "o": ["A. 直接还原", "B. dCMP脱氨酶→dUMP", "C. dUDP→dUMP(dUDP酶)", "D. dCMP+FH4"], "a": "B", "e": "dCMP+H2O→脱氨酶→dUMP+NH3。dUMP是dTMP合成的直接前体。", "kp": "nucleic_s3_0"}, {"id": "nucleic_mcq_29", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "人类为何比多数哺乳动物更易患痛风？", "o": ["A. 嘌呤摄入过多", "B. 缺乏尿酸酶,尿酸不能再氧化为更易溶的尿囊素", "C. 黄嘌呤氧化酶活性过高", "D. 肾脏排泄障碍"], "a": "B", "e": "人/灵长类在进化中丢失了尿酸酶(尿酸氧化酶)基因→尿酸不能再氧化为水溶性好的尿囊素(allantoin)→尿酸积累→痛风。", "kp": "nucleic_s3_3"}, {"id": "nucleic_mcq_30", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "乳清酸尿症(Orotic aciduria)的酶缺陷是什么？", "o": ["A. HGPRT缺陷", "B. UMP合成酶(OPRT+OMP脱羧酶双功能酶)缺陷", "C. 黄嘌呤氧化酶缺陷", "D. 腺苷脱氨酶缺陷"], "a": "B", "e": "UMP合成酶(乳清酸磷酸核糖转移酶+乳清苷酸脱羧酶双功能酶)缺陷→嘧啶从头合成受阻→乳清酸积累→巨幼红细胞性贫血(对叶酸/B12治疗无效),可用尿苷治疗。", "kp": "nucleic_s3_3"}, {"id": "nucleic_mcq_31", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "腺苷脱氨酶(ADA)缺陷导致严重联合免疫缺陷(SCID)的机制是什么？", "o": ["A. 尿酸积累", "B. dATP积累→抑制核糖核苷酸还原酶→dNTP不足→淋巴细胞不能增殖", "C. 乳清酸积累", "D. FH4缺乏"], "a": "B", "e": "ADA缺陷→腺苷/脱氧腺苷积累→dATP升高→dATP别构抑制核糖核苷酸还原酶→dNTP不足→DNA合成受阻→淋巴细胞不能增殖→SCID。首个用基因治疗成功的疾病(1990)。", "kp": "nucleic_s3_0"}, {"id": "nucleic_mcq_32", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "dUTPase(dUTP焦磷酸酶)的主要生理作用是什么？", "o": ["A. 合成dTMP", "B. 水解dUTP→dUMP+PPi,降低dUTP池防止其掺入DNA", "C. 合成ATP", "D. 还原核糖核苷酸"], "a": "B", "e": "dUTPase将dUTP水解为dUMP+PPi:①降低dUTP浓度,防止dUTP代替dTTP掺入DNA(避免U错配)→②生成的dUMP是dTMP合成的前体。一举两得!", "kp": "nucleic_s3_4"}], "judge": [], "fill": [{"id": "nucleic_fill_6", "modI": 3, "q": "核糖核苷酸还原的底物是________,还原剂为________,其再生需________酶和________。", "a": "NDP(核苷二磷酸),硫氧还蛋白,硫氧还蛋白还原酶,NADPH", "kp": "nucleic_s3_5"}, {"id": "nucleic_fill_7", "modI": 3, "q": "dTMP由________经胸苷酸合成酶催化生成,甲基供体是________,生成的FH2经________还原为FH4再生。", "a": "dUMP,N5,N10-CH2-FH4,二氢叶酸还原酶(DHFR)", "kp": "nucleic_s3_0"}, {"id": "nucleic_fill_9", "modI": 3, "q": "嘌呤补救途径中AMP/GMP以________途径为主(关键酶________、________),CMP/UMP/dTMP以________途径为主。", "a": "磷酸核糖转移酶,APRT(腺嘌呤磷酸核糖转移酶),HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶),核苷磷酸化酶+核苷激酶", "kp": "nucleic_s3_2"}, {"id": "nucleic_fill_10", "modI": 3, "q": "核苷一磷酸激酶催化________→________,核苷二磷酸激酶催化________→________,后者是________(底物特性)。", "a": "NMP,NDP,NDP,NTP,底物广泛(催化多种核苷酸)", "kp": "nucleic_s3_4"}, {"id": "nucleic_fill_12", "modI": 3, "q": "腺苷脱氨酶(ADA)缺陷导致________病,其机制是________积累抑制核糖核苷酸还原酶。", "a": "严重联合免疫缺陷(SCID),dATP", "kp": "nucleic_s3_5"}], "short": [{"id": "nucleic_short_4", "modI": 3, "q": "简述嘌呤核苷酸和嘧啶核苷酸的补救合成途径及其生理意义。", "a": "补救合成(利用现成碱基/核苷):\u000b\u000b【嘌呤补救】以磷酸核糖转移酶为主:\u000b• 腺嘌呤+PRPP→AMP+PPi(APRT催化)\u000b• 次黄嘌呤/鸟嘌呤+PRPP→IMP/GMP(HGPRT催化)\u000b\u000b【嘧啶补救】以核苷磷酸化酶+核苷激酶为主:\u000b• 尿嘧啶+核糖-1-P→尿苷→尿苷激酶+ATP→UMP\u000b\u000b生理意义:\u000b①节约能量和原料(从头合成耗ATP大量)\u000b②脑组织几乎完全依赖补救途径(缺乏从头合成酶)\u000b③HGPRT缺陷→Lesch-Nyhan综合症→证明补救途径对神经系统的关键作用\u000b④红细胞等成熟细胞也依赖补救途径维持核苷酸池", "kp": "nucleic_s3_5"}, {"id": "nucleic_short_8", "modI": 3, "q": "简述核苷酸代谢相关的遗传性疾病及其生化基础。", "a": "核苷酸代谢遗传病体现关键酶的重要作用:\u000b\u000b【Lesch-Nyhan综合症】\u000b• 缺陷酶:HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)\u000b• 机制:嘌呤补救途径受阻→PRPP积累→从头合成亢进→尿酸大量产生\u000b• 症状:高尿酸血症(痛风)、自残行为、智力障碍、神经损害\u000b• 遗传:X连锁隐性\u000b\u000b【乳清酸尿症】\u000b• 缺陷酶:UMP合成酶(OPRT+OMP脱羧酶双功能酶)\u000b• 机制:嘧啶从头合成受阻→乳清酸积累→嘧啶核苷酸不足\u000b• 症状:巨幼红细胞性贫血(对叶酸/B12治疗无效)\u000b• 治疗:补充尿苷(绕过缺陷酶)\u000b\u000b【ADA缺陷→SCID】\u000b• 缺陷酶:腺苷脱氨酶(ADA)\u000b• 机制:腺苷/dAdo积累→dATP↑→抑制核糖核苷酸还原酶→dNTP不足→淋巴细胞不能增殖\u000b• 症状:严重联合免疫缺陷(SCID)\u000b• 意义:首个基因治疗成功的疾病(1990)\u000b\u000b【原发性痛风】\u000b• 原因:人缺乏尿酸酶→尿酸不能氧化为尿囊素→积累\u000b• 或:PRPP合成酶活性过高→嘌呤合成亢进\u000b• 症状:尿酸钠结晶沉积关节→剧痛\u000b\u000b共同点:均为单一酶缺陷→代谢中间物积累→毒性效应", "kp": "nucleic_s3_4"}], "calc": [{"id": "nucleic_calc_4", "modI": 3, "q": "论述核苷酸代谢与糖/脂/蛋白质代谢的联系(四大物质代谢的整合)。", "a": "核苷酸代谢与三大物质代谢通过前体和产物紧密联系", "steps": "【核苷酸合成前体来自其他代谢】\u000b①PRPP的5-P核糖→来自PPP(糖代谢)\u000b②嘌呤/嘧啶的N→来自Gln/Asp(氨基酸代谢)\u000b③Gly/Asp→嘌呤环的C/N(氨基酸代谢)\u000b④CO2→羧基来源(呼吸代谢)\u000b⑤一碳单位→来自Ser/Gly分解(氨基酸代谢)\u000b⑥嘧啶的Asp→来自OAA(转氨,TCA中间物)\u000b\u000b【核苷酸分解产物进入其他代谢】\u000b①嘌呤→尿酸→排出(人类)\u000b②嘧啶→β-丙氨酸→乙酰CoA→TCA\u000b③胸腺嘧啶→β-氨基异丁酸→琥珀酰CoA→TCA\u000b④戊糖-1-P→戊糖-5-P→PPP\u000b\u000b【核苷酸是辅酶/能量物质前体】\u000b①ATP/GTP→能量代谢核心\u000b②AMP→NAD+/NADP+/FAD/CoA→三大代谢的辅酶\u000b③核苷酸→信号分子(cAMP/cGMP)→代谢调节\u000b\u000b总结:核苷酸代谢通过前体供给和产物回补,与糖/脂/蛋白质代谢形成完整网络,TCA是枢纽", "kp": "nucleic_s3_6"}], "term": [{"id": "nucleic_term_8", "modI": 3, "term": "补救途径(Salvage Pathway)", "def": "①利用现成碱基或核苷与PRPP/核糖-1-磷酸重新合成核苷酸的途径（定义）。②途径：碱基+PRPP→核苷酸(磷酸核糖转移酶)；或碱基+核糖-1-P→核苷→核苷酸(核苷磷酸化酶+核苷激酶)（途径）。③关键酶：APRT(腺嘌呤磷酸核糖转移酶)、HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)（关键酶）。④意义：节约能量(1个~P vs 从头合成5-7个~P)、脑组织几乎全依赖补救途径（意义）。⑤病理：HGPRT缺陷→Lesch-Nyhan综合症（病理）。", "kps": "①定义(1分)②两种途径(1分)③关键酶(1分)④意义(1分)⑤病理(1分)", "kp": "nucleic_s3_2"}, {"id": "nucleic_term_9", "modI": 3, "term": "HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)", "def": "①催化次黄嘌呤/鸟嘌呤+PRPP→IMP/GMP+PPi的补救合成酶（定义）。②功能：嘌呤补救途径的关键酶（功能）。③意义：脑组织依赖此酶维持核苷酸池(脑缺从头合成酶)（意义）。④缺陷：Lesch-Nyhan综合症——X连锁隐性遗传，表现为尿酸过多(痛风)、自残行为、智力障碍、神经损害（缺陷）。⑤机制：HGPRT缺陷→补救受阻→PRPP积累→从头合成亢进→尿酸大量生成（机制）。", "kps": "①定义(1分)②功能(1分)③脑组织意义(1分)④Lesch-Nyhan(1分)⑤机制(1分)", "kp": "nucleic_s3_2"}, {"id": "nucleic_term_10", "modI": 3, "term": "Lesch-Nyhan综合症", "def": "①HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)完全或严重缺陷导致的X连锁隐性遗传病（定义）。②生化机制：补救途径受阻→PRPP积累→嘌呤从头合成亢进→尿酸大量产生→痛风（生化）。③症状：高尿酸血症(痛风)、自残行为(咬手指/唇)、智力发育迟缓、锥体外系神经症状（症状）。④意义：证明嘌呤补救途径对神经系统(尤其脑)的关键作用（意义）。⑤诊断/治疗：测定HGPRT活性、别嘌呤醇控制尿酸（诊疗）。", "kps": "①HGPRT缺陷(1分)②生化机制(1分)③症状(1分)④意义(1分)⑤诊疗(1分)", "kp": "nucleic_s3_3"}, {"id": "nucleic_term_19", "modI": 3, "term": "胸苷酸合成酶(Thymidylate Synthase)", "def": "①催化dUMP甲基化为dTMP的酶（定义）。②反应：dUMP+N5,N10-CH2-FH4→dTMP+FH2（反应）。③甲基供体：N5,N10-亚甲基四氢叶酸(一碳单位)（甲基供体）。④产物：FH2需DHFR还原为FH4再生（再生）。⑤临床：5-FU→5-FdUMP→不可逆抑制此酶→抗癌（临床）。", "kps": "①定义(1分)②反应(1分)③甲基供体(1分)④FH2再生(1分)⑤5-FU抑制(1分)", "kp": "nucleic_s3_1"}, {"id": "nucleic_term_23", "modI": 3, "term": "腺苷脱氨酶缺陷/SCID(ADA Deficiency)", "def": "①腺苷脱氨酶(ADA)缺陷导致的严重联合免疫缺陷(SCID)（定义）。②ADA功能：催化腺苷→次黄苷、脱氧腺苷→脱氧次黄苷(嘌呤分解代谢)（功能）。③机制：ADA缺陷→腺苷/脱氧腺苷积累→经激酶→dATP↑→dATP别构抑制核糖核苷酸还原酶→dNTP不足→DNA合成受阻→淋巴细胞不能增殖（机制）。④症状：T/B淋巴细胞都缺陷→严重联合免疫缺陷→反复严重感染（症状）。⑤意义：1990年首个基因治疗成功的疾病(Ashanti DeSilva)（意义）。", "kps": "①定义(1分)②ADA功能(1分)③dATP抑制RNR机制(2分)④SCID症状(1分)⑤基因治疗里程碑(1分)", "kp": "nucleic_s3_0"}, {"id": "nucleic_term_26", "modI": 3, "term": "腺苷激酶(Adenosine Kinase)", "def": "①催化腺苷+ATP→AMP+ADP的酶（定义）。②功能：腺苷补救合成AMP的直接途径(不需PRPP,与APRT利用腺嘌呤+PRPP不同)（功能）。③意义：腺苷激酶+腺苷脱氨酶共同决定细胞内腺苷的浓度→腺苷是重要的信号分子(调节血管舒张、神经活动等)（意义）。④与其他补救途径的关系：APRT(腺嘌呤+PRPP→AMP)、HGPRT(次黄嘌呤/鸟嘌呤+PRPP)、腺苷激酶(腺苷+ATP→AMP)三条嘌呤补救途径（关系）。⑤临床：腺苷激酶抑制剂可升高腺苷浓度→用于抗炎、镇痛、抗癫痫等研究（临床）。", "kps": "①定义(1分)②腺苷补救(1分)③腺苷信号调节(1分)④三补救途径(1分)⑤临床意义(1分)", "kp": "nucleic_s3_2"}]}], "mcq": [{"id": "nucleic_mcq_1", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "核酸酶按作用位点分为哪两类？", "o": ["A. RNase和DNase", "B. 核酸内切酶和核酸外切酶", "C. 核苷酸酶和核苷酶", "D. 磷酸二酯酶和磷酸单酯酶"], "a": "B", "e": "按作用位点：内切酶(切内部)/外切酶(从末端)。按底物：RNase/DNase。蛇毒→5'-核苷酸,牛脾→3'-核苷酸。", "kp": "nucleic_s0_2"}, {"id": "nucleic_mcq_2", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "蛇毒磷酸二酯酶水解核酸的产物是什么？", "o": ["A. 3'-核苷酸", "B. 5'-核苷酸", "C. 核苷+Pi", "D. 碱基+戊糖"], "a": "B", "e": "蛇毒磷酸二酯酶→5'-核苷酸。牛脾磷酸二酯酶→3'-核苷酸。两者都是核酸外切酶。", "kp": "nucleic_s0_2"}, {"id": "nucleic_mcq_3", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "嘌呤碱基分解代谢的终产物是什么？", "o": ["A. 尿素", "B. 尿酸", "C. β-丙氨酸", "D. 氨"], "a": "B", "e": "嘌呤(腺嘌呤/鸟嘌呤)→黄嘌呤→黄嘌呤氧化酶→尿酸。尿酸水溶性低→积累致痛风。", "kp": "nucleic_s0_1"}, {"id": "nucleic_mcq_4", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "嘧啶碱基分解代谢的终产物是什么？", "o": ["A. 尿酸", "B. β-丙氨酸/β-氨基异丁酸+NH3+CO2", "C. 尿素", "D. 乙酰CoA"], "a": "B", "e": "胞嘧啶/尿嘧啶→β-丙氨酸；胸腺嘧啶→β-氨基异丁酸。均为水溶性开环产物,易排出。", "kp": "nucleic_s0_1"}, {"id": "nucleic_mcq_5", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "催化次黄嘌呤→黄嘌呤→尿酸的酶是什么？", "o": ["A. 腺苷脱氨酶", "B. 黄嘌呤氧化酶", "C. 鸟嘌呤脱氨酶", "D. 核苷磷酸化酶"], "a": "B", "e": "黄嘌呤氧化酶(含FAD/Mo/铁硫簇)催化最后两步氧化→尿酸。别嘌呤醇抑制此酶→治疗痛风。", "kp": "nucleic_s0_5"}, {"id": "nucleic_mcq_6", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "痛风症的病因是什么？", "o": ["A. 尿酸酶过多", "B. 尿酸过多积累形成结晶沉积关节", "C. 嘌呤合成不足", "D. 嘧啶积累"], "a": "B", "e": "尿酸水溶性低→过饱和→尿酸钠结晶→关节沉积→炎症疼痛。治疗：别嘌呤醇。", "kp": "nucleic_s0_7"}, {"id": "nucleic_mcq_7", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "别嘌呤醇治疗痛风的机制是什么？", "o": ["A. 促进尿酸排出", "B. 抑制黄嘌呤氧化酶→减少尿酸生成", "C. 抑制嘌呤合成", "D. 促进嘌呤分解"], "a": "B", "e": "别嘌呤醇是黄嘌呤氧化酶竞争性抑制剂→且本身被氧化为别黄嘌呤(更强抑制剂)→阻断尿酸生成。", "kp": "nucleic_s0_7"}, {"id": "nucleic_mcq_8", "mod": "模块一：核酸/核苷酸分解", "modI": 0, "q": "嘌呤环中N1原子来自哪个前体？", "o": ["A. 甘氨酸", "B. 天冬氨酸", "C. 谷氨酰胺", "D. CO2"], "a": "B", "e": "嘌呤环：N1→Asp；N3/N9→Gln；N7+C4+C5→Gly；C6→CO2；C2/C8→N10-甲酰FH4。", "kp": "nucleic_s0_5"}, {"id": "nucleic_mcq_9", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤环中C2和C8原子来自什么？", "o": ["A. 甘氨酸", "B. 一碳单位(N10-CHO-FH4)", "C. CO2", "D. 天冬氨酸"], "a": "B", "e": "C2+C8→N10-甲酰FH4(一碳单位)。Gly给C4/C5/N7,Asp给N1,Gln给N3/N9,CO2给C6。", "kp": "nucleic_s1_4"}, {"id": "nucleic_mcq_10", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤从头合成的直接前体是什么？", "o": ["A. 葡萄糖", "B. PRPP(5-磷酸核糖焦磷酸)", "C. 核糖", "D. 脱氧核糖"], "a": "B", "e": "PRPP是嘌呤从头合成起点。由5-磷酸核糖+ATP经PRPP合成酶生成。", "kp": "nucleic_s1_4"}, {"id": "nucleic_mcq_11", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤从头合成的第一个完整核苷酸产物是什么？", "o": ["A. AMP", "B. GMP", "C. IMP(次黄苷酸)", "D. XMP"], "a": "C", "e": "IMP(次黄苷酸)是母体核苷酸→再分支生成AMP和GMP。", "kp": "nucleic_s1_4"}, {"id": "nucleic_mcq_12", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "IMP→AMP需要什么？", "o": ["A. Asp+GTP", "B. Gln+ATP", "C. NAD+", "D. 一碳单位"], "a": "A", "e": "IMP+Asp+GTP→腺苷酸代琥珀酸→AMP+延胡索酸。IMP→GMP需NAD++Gln+ATP。", "kp": "nucleic_s1_7"}, {"id": "nucleic_mcq_13", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘌呤合成中由IMP→GMP需要哪两个酶？", "o": ["A. IMP脱氢酶+GMP合成酶", "B. 腺苷酸合成酶", "C. 脱氨酶", "D. 磷酸化酶"], "a": "A", "e": "IMP+NAD+→IMP脱氢酶→XMP→GMP合成酶(Gln+ATP)→GMP。", "kp": "nucleic_s1_7"}, {"id": "nucleic_mcq_14", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "6-巯基嘌呤(6-MP)的抗癌机制是什么？", "o": ["A. 抑制黄嘌呤氧化酶", "B. 嘌呤类似物,抑制IMP参与的反应", "C. 抑制嘧啶合成", "D. 抑制DHFR"], "a": "B", "e": "6-MP是嘌呤类似物→抑制IMP及后续反应→阻断嘌呤/核酸合成→用于白血病等抗癌治疗。", "kp": "nucleic_s1_7"}, {"id": "nucleic_mcq_15", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "氨甲喋呤(MTX)的作用机制是什么？", "o": ["A. 抑制黄嘌呤氧化酶", "B. 与二氢叶酸还原酶不可逆结合→抑制FH4", "C. 抑制胸苷酸合成酶", "D. 抑制Asp转氨甲酰酶"], "a": "B", "e": "MTX(叶酸类似物)→不可逆抑制DHFR→FH4不能再生→一碳单位转移受阻→嘌呤/胸苷酸合成受阻→抗癌。", "kp": "nucleic_s1_0"}, {"id": "nucleic_mcq_16", "mod": "模块二：嘌呤/嘧啶从头合成", "modI": 1, "q": "嘧啶环中C4、C5、C6原子来自什么？", "o": ["A. 甘氨酸", "B. 天冬氨酸(完整提供)", "C. 谷氨酰胺", "D. CO2"], "a": "B", "e": "嘧啶环：Asp完整提供C4/C5/C6；N1→Gln；C2→CO2；N3→Asp。", "kp": "nucleic_s1_4"}, {"id": "nucleic_mcq_17", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "嘧啶从头合成与嘌呤从头合成的关键区别是什么？", "o": ["A. 完全无区别", "B. 嘧啶先合成嘧啶环再连PRPP,嘌呤先PRPP后建环", "C. 嘌呤先成环", "D. 两者都不需PRPP"], "a": "B", "e": "嘧啶：先合成乳清酸(完整嘧啶环)→再+PRPP→OMP→UMP。嘌呤：先PRPP→逐步在PRPP上构建嘌呤环→IMP。", "kp": "nucleic_s2_3"}, {"id": "nucleic_mcq_18", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "嘧啶合成中关键调控酶是什么？", "o": ["A. 氨甲酰磷酸合成酶II(CPS-II)", "B. 天冬氨酸转氨甲酰酶(ATCase)", "C. 乳清酸脱羧酶", "D. UMP激酶"], "a": "B", "e": "ATCase是嘧啶合成关键调控酶→受CTP反馈抑制→控制嘧啶合成速率。", "kp": "nucleic_s2_4"}, {"id": "nucleic_mcq_19", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "CTP由哪个核苷酸转变而来？", "o": ["A. UMP", "B. UTP→CTP合成酶(Gln)", "C. 直接合成", "D. dCMP"], "a": "B", "e": "UMP→UDP→UTP→CTP合成酶(Gln+ATP)→CTP。", "kp": "nucleic_s2_5"}, {"id": "nucleic_mcq_20", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "核糖核苷酸还原的底物是什么？", "o": ["A. NMP", "B. NDP(二磷酸核糖核苷)", "C. NTP", "D. 碱基"], "a": "B", "e": "核糖核苷酸还原酶作用于NDP(ADP/GDP/CDP/UDP)→dNDP。还原剂硫氧还蛋白+NADPH。", "kp": "nucleic_s2_6"}, {"id": "nucleic_mcq_21", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "dTMP合成的直接前体和甲基供体是什么？", "o": ["A. dCMP+SAM", "B. dUMP+N5,N10-CH2-FH4", "C. dUDP+FH4", "D. T+PRPP"], "a": "B", "e": "dUMP+胸苷酸合成酶(N5,N10-CH2-FH4供甲基)→dTMP+FH2。FH2→DHFR→FH4再生。5-FU抑制此酶。", "kp": "nucleic_s2_0"}, {"id": "nucleic_mcq_22", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "5-氟尿嘧啶(5-FU)的抗癌机制是什么？", "o": ["A. 抑制黄嘌呤氧化酶", "B. 转成5-FdUMP→抑制胸苷酸合成酶", "C. 抑制DHFR", "D. 抑制ATCase"], "a": "B", "e": "5-FU在体内→5-FdUMP→与胸苷酸合成酶不可逆结合→阻断dTMP合成→DNA合成受阻→抗癌。", "kp": "nucleic_s2_3"}, {"id": "nucleic_mcq_23", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "嘌呤补救途径中,AMP和GMP合成以哪条为主？", "o": ["A. 核苷磷酸化酶途径", "B. 磷酸核糖转移酶途径(碱基+PRPP)", "C. 核苷激酶途径", "D. 从头合成"], "a": "B", "e": "AMP/GMP/IMP补救合成以磷酸核糖转移酶(碱基+PRPP)为主；CMP/UMP/dTMP以核苷磷酸化酶+核苷激酶为主。", "kp": "nucleic_s2_0"}, {"id": "nucleic_mcq_24", "mod": "模块三：脱氧核苷酸/补救合成", "modI": 2, "q": "Lesch-Nyhan综合症的分子病因是什么？", "o": ["A. APRT缺陷", "B. HGPRT缺陷", "C. 黄嘌呤氧化酶缺陷", "D. 腺苷脱氨酶缺陷"], "a": "B", "e": "HGPRT缺陷(X连锁隐性)→补救途径受阻→PRPP积累→从头合成亢进→尿酸过多→痛风+自残+神经损害。", "kp": "nucleic_s2_2"}, {"id": "nucleic_mcq_25", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "核苷二磷酸激酶的作用是什么？", "o": ["A. NMP→NDP", "B. NDP→NTP(底物广泛)", "C. 核苷→核苷酸", "D. 碱基→核苷"], "a": "B", "e": "核苷二磷酸激酶催化NDP+ATP→NTP+ADP,底物广泛。核苷一磷酸激酶催化NMP→NDP。", "kp": "nucleic_s3_4"}, {"id": "nucleic_mcq_26", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "嘧啶分解产生的β-丙氨酸最终去向？", "o": ["A. 直接排出", "B. 转氨→乙酰CoA(可进入代谢)", "C. 生成尿酸", "D. 生成尿素"], "a": "B", "e": "β-丙氨酸→转氨→丙二酸半醛→乙酰CoA。胸腺嘧啶→β-氨基异丁酸→琥珀酰CoA。", "kp": "nucleic_s3_6"}, {"id": "nucleic_mcq_27", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "嘌呤核苷酸从头合成的限速反应是什么？", "o": ["A. IMP→AMP", "B. PRPP+Gln→PRA(转酰胺酶)", "C. IMP→GMP", "D. 磷酸核糖焦磷酸激酶"], "a": "B", "e": "PRPP+Gln→PRA(5-磷酸核糖胺)是嘌呤从头合成第一个限速反应→受AMP/GMP反馈抑制。", "kp": "nucleic_s3_5"}, {"id": "nucleic_mcq_28", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "dCMP如何转变为dUMP？", "o": ["A. 直接还原", "B. dCMP脱氨酶→dUMP", "C. dUDP→dUMP(dUDP酶)", "D. dCMP+FH4"], "a": "B", "e": "dCMP+H2O→脱氨酶→dUMP+NH3。dUMP是dTMP合成的直接前体。", "kp": "nucleic_s3_0"}, {"id": "nucleic_mcq_29", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "人类为何比多数哺乳动物更易患痛风？", "o": ["A. 嘌呤摄入过多", "B. 缺乏尿酸酶,尿酸不能再氧化为更易溶的尿囊素", "C. 黄嘌呤氧化酶活性过高", "D. 肾脏排泄障碍"], "a": "B", "e": "人/灵长类在进化中丢失了尿酸酶(尿酸氧化酶)基因→尿酸不能再氧化为水溶性好的尿囊素(allantoin)→尿酸积累→痛风。", "kp": "nucleic_s3_3"}, {"id": "nucleic_mcq_30", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "乳清酸尿症(Orotic aciduria)的酶缺陷是什么？", "o": ["A. HGPRT缺陷", "B. UMP合成酶(OPRT+OMP脱羧酶双功能酶)缺陷", "C. 黄嘌呤氧化酶缺陷", "D. 腺苷脱氨酶缺陷"], "a": "B", "e": "UMP合成酶(乳清酸磷酸核糖转移酶+乳清苷酸脱羧酶双功能酶)缺陷→嘧啶从头合成受阻→乳清酸积累→巨幼红细胞性贫血(对叶酸/B12治疗无效),可用尿苷治疗。", "kp": "nucleic_s3_3"}, {"id": "nucleic_mcq_31", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "腺苷脱氨酶(ADA)缺陷导致严重联合免疫缺陷(SCID)的机制是什么？", "o": ["A. 尿酸积累", "B. dATP积累→抑制核糖核苷酸还原酶→dNTP不足→淋巴细胞不能增殖", "C. 乳清酸积累", "D. FH4缺乏"], "a": "B", "e": "ADA缺陷→腺苷/脱氧腺苷积累→dATP升高→dATP别构抑制核糖核苷酸还原酶→dNTP不足→DNA合成受阻→淋巴细胞不能增殖→SCID。首个用基因治疗成功的疾病(1990)。", "kp": "nucleic_s3_0"}, {"id": "nucleic_mcq_32", "mod": "模块四：核苷酸与核酸代谢关系", "modI": 3, "q": "dUTPase(dUTP焦磷酸酶)的主要生理作用是什么？", "o": ["A. 合成dTMP", "B. 水解dUTP→dUMP+PPi,降低dUTP池防止其掺入DNA", "C. 合成ATP", "D. 还原核糖核苷酸"], "a": "B", "e": "dUTPase将dUTP水解为dUMP+PPi:①降低dUTP浓度,防止dUTP代替dTTP掺入DNA(避免U错配)→②生成的dUMP是dTMP合成的前体。一举两得!", "kp": "nucleic_s3_4"}], "judge": [], "fill": [{"id": "nucleic_fill_1", "modI": 0, "q": "嘌呤碱基分解的终产物是________,嘧啶碱基(胞嘧啶/尿嘧啶)分解的终产物是________,胸腺嘧啶分解的终产物是________。", "a": "尿酸,β-丙氨酸,β-氨基异丁酸", "kp": "nucleic_s0_5"}, {"id": "nucleic_fill_2", "modI": 1, "q": "嘌呤环中N1来自________,N3和N9来自________,C2和C8来自________,C6来自________。", "a": "天冬氨酸(Asp),谷氨酰胺(Gln),N10-甲酰FH4(一碳单位),CO2", "kp": "nucleic_s1_4"}, {"id": "nucleic_fill_3", "modI": 2, "q": "嘌呤从头合成的直接前体是________,其第一个完整核苷酸产物是________,再由它分支生成________和________。", "a": "PRPP(5-磷酸核糖焦磷酸),IMP(次黄苷酸),AMP,GMP", "kp": "nucleic_s2_3"}, {"id": "nucleic_fill_4", "modI": 2, "q": "嘧啶环中N1来自________,C2来自________,C4/C5/C6完整来自________。嘧啶合成先形成________再与PRPP结合。", "a": "谷氨酰胺(Gln),CO2,天冬氨酸(Asp),乳清酸(嘧啶环)", "kp": "nucleic_s2_3"}, {"id": "nucleic_fill_5", "modI": 0, "q": "痛风症的常用治疗药物是________,它抑制________酶。Lesch-Nyhan综合症是________酶缺陷导致。", "a": "别嘌呤醇,黄嘌呤氧化酶,HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)", "kp": "nucleic_s0_7"}, {"id": "nucleic_fill_6", "modI": 3, "q": "核糖核苷酸还原的底物是________,还原剂为________,其再生需________酶和________。", "a": "NDP(核苷二磷酸),硫氧还蛋白,硫氧还蛋白还原酶,NADPH", "kp": "nucleic_s3_5"}, {"id": "nucleic_fill_7", "modI": 3, "q": "dTMP由________经胸苷酸合成酶催化生成,甲基供体是________,生成的FH2经________还原为FH4再生。", "a": "dUMP,N5,N10-CH2-FH4,二氢叶酸还原酶(DHFR)", "kp": "nucleic_s3_0"}, {"id": "nucleic_fill_8", "modI": 2, "q": "5-氟尿嘧啶(5-FU)转成________抑制________酶;氨甲喋呤抑制________酶;6-巯基嘌呤是________类似物。", "a": "5-FdUMP,胸苷酸合成酶,二氢叶酸还原酶(DHFR),嘌呤", "kp": "nucleic_s2_2"}, {"id": "nucleic_fill_9", "modI": 3, "q": "嘌呤补救途径中AMP/GMP以________途径为主(关键酶________、________),CMP/UMP/dTMP以________途径为主。", "a": "磷酸核糖转移酶,APRT(腺嘌呤磷酸核糖转移酶),HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶),核苷磷酸化酶+核苷激酶", "kp": "nucleic_s3_2"}, {"id": "nucleic_fill_10", "modI": 3, "q": "核苷一磷酸激酶催化________→________,核苷二磷酸激酶催化________→________,后者是________(底物特性)。", "a": "NMP,NDP,NDP,NTP,底物广泛(催化多种核苷酸)", "kp": "nucleic_s3_4"}, {"id": "nucleic_fill_11", "modI": 0, "q": "人类和灵长类缺乏________酶,故嘌呤分解终产物是________,而其他哺乳动物可进一步氧化为________。", "a": "尿酸酶(尿酸氧化酶),尿酸,尿囊素(allantoin)", "kp": "nucleic_s0_6"}, {"id": "nucleic_fill_12", "modI": 3, "q": "腺苷脱氨酶(ADA)缺陷导致________病,其机制是________积累抑制核糖核苷酸还原酶。", "a": "严重联合免疫缺陷(SCID),dATP", "kp": "nucleic_s3_5"}], "short": [{"id": "nucleic_short_1", "modI": 1, "q": "简述嘌呤核苷酸从头合成的全过程,标明嘌呤环各原子的来源。", "a": "嘌呤从头合成部位：肝(主要)。过程分两个阶段。\u000b\u000b【第一阶段:IMP合成】\u000b①5-P核糖+ATP→PRPP(PRPP合成酶)\u000b②PRPP+Gln→PRA(转酰胺酶,限速反应)\u000b③PRA+Gly→GAR(Gly提供C4C5N7)\u000b④GAR+N10-CHO-FH4→FGAR(提供C8)\u000b⑤FGAR+Gln→FGAM(提供N3)\u000b⑥环化→AIR(咪唑环闭合)\u000b⑦AIR+CO2→CAIR(提供C6)\u000b⑧CAIR+Asp→SAICAR(提供N1)\u000b⑨SAICAR→AICAR(裂解出延胡索酸)\u000b⑩AICAR+N10-CHO-FH4→FAICAR(提供C2)\u000b⑪FAICAR→IMP(环化)\u000b\u000b【第二阶段:IMP→AMP/GMP】\u000b• IMP+Asp+GTP→腺苷酸代琥珀酸→AMP\u000b• IMP+NAD+→XMP→GMP(Gln+ATP)\u000b\u000b嘌呤环原子来源:\u000bN1→Asp;N3/N9→Gln;N7+C4+C5→Gly;C6→CO2;C2/C8→一碳单位", "kp": "nucleic_s1_4"}, {"id": "nucleic_short_2", "modI": 1, "q": "比较嘌呤和嘧啶核苷酸从头合成的异同。", "a": "相同点:\u000b①都以PRPP为核糖磷酸供体\u000b②都需氨基酸(Gln/Asp)、CO2、一碳单位等前体\u000b③都是能量消耗大的合成过程\u000b\u000b不同点:\u000b①环构建顺序:嘌呤→先在PRPP上逐步构建嘌呤环→IMP;嘧啶→先合成完整嘧啶环(乳清酸)→再与PRPP结合→UMP\u000b②原子来源:嘌呤N1→Asp,C2/C8→一碳单位;嘧啶C4C5C6→Asp完整提供\u000b③首个产物:嘌呤→IMP;嘧啶→UMP\u000b④关键调控酶:嘌呤→PRPP转酰胺酶/PRPP合成酶;嘧啶→ATCase(受CTP反馈抑制)\u000b⑤部位:嘌呤主要在肝;嘧啶在多种组织", "kp": "nucleic_s1_4"}, {"id": "nucleic_short_3", "modI": 2, "q": "简述嘧啶核苷酸从头合成途径,标明关键调控酶。", "a": "嘧啶从头合成(细胞质):\u000b\u000b【嘧啶环合成】\u000b①Gln+CO2+2ATP→氨甲酰磷酸(CPS-II)\u000b②氨甲酰磷酸+Asp→氨甲酰Asp(ATCase★关键调控酶)\u000b③氨甲酰Asp→二氢乳清酸(二氢乳清酸酶)\u000b④二氢乳清酸→乳清酸(二氢乳清酸脱氢酶)\u000b\u000b【连接PRPP】\u000b⑤乳清酸+PRPP→OMP(乳清苷酸转移酶)\u000b⑥OMP→UMP(脱羧酶)\u000b\u000b【磷酸化】\u000b⑦UMP→UDP→UTP\u000b⑧UTP+Gln→CTP(CTP合成酶)\u000b\u000b调控:\u000b★ATCase受CTP反馈抑制(别构)→嘧啶合成的关键调控点\u000bCPS-II受UMP反馈抑制\u000b\u000b注意:与嘌呤不同,嘧啶先成环后连PRPP", "kp": "nucleic_s2_3"}, {"id": "nucleic_short_4", "modI": 3, "q": "简述嘌呤核苷酸和嘧啶核苷酸的补救合成途径及其生理意义。", "a": "补救合成(利用现成碱基/核苷):\u000b\u000b【嘌呤补救】以磷酸核糖转移酶为主:\u000b• 腺嘌呤+PRPP→AMP+PPi(APRT催化)\u000b• 次黄嘌呤/鸟嘌呤+PRPP→IMP/GMP(HGPRT催化)\u000b\u000b【嘧啶补救】以核苷磷酸化酶+核苷激酶为主:\u000b• 尿嘧啶+核糖-1-P→尿苷→尿苷激酶+ATP→UMP\u000b\u000b生理意义:\u000b①节约能量和原料(从头合成耗ATP大量)\u000b②脑组织几乎完全依赖补救途径(缺乏从头合成酶)\u000b③HGPRT缺陷→Lesch-Nyhan综合症→证明补救途径对神经系统的关键作用\u000b④红细胞等成熟细胞也依赖补救途径维持核苷酸池", "kp": "nucleic_s3_5"}, {"id": "nucleic_short_5", "modI": 2, "q": "简述核糖核苷酸还原酶的作用机制和dTMP的合成过程。", "a": "【核糖核苷酸还原】\u000b• 底物:NDP(ADP/GDP/CDP/UDP)→dNDP\u000b• 酶:核糖核苷酸还原酶(含铁/酪氨酸自由基)\u000b• 还原剂:硫氧还蛋白(SH)2→氧化为S-S\u000b• 再生:硫氧还蛋白还原酶+NADPH\u000b• 产物dNDP→磷酸化→dNTP→DNA合成前体\u000b\u000b【dTMP合成】\u000b• dUMP+N5,N10-CH2-FH4→胸苷酸合成酶→dTMP+FH2\u000b• 甲基供体:N5,N10-亚甲基FH4(一碳单位)\u000b• FH2→二氢叶酸还原酶(DHFR)→FH4再生\u000b\u000bdUMP来源:\u000b①dCMP→脱氨酶→dUMP\u000b②dUDP→dUDP酶→dUMP\u000b\u000b药物靶点:\u000b5-FU→5-FdUMP→抑制胸苷酸合成酶(抗癌)\u000bMTX→抑制DHFR→阻断FH4再生(抗癌)", "kp": "nucleic_s2_6"}, {"id": "nucleic_short_6", "modI": 0, "q": "简述嘌呤核苷酸分解代谢的全过程和痛风症的生化基础及治疗。", "a": "【嘌呤分解过程】\u000b①核苷酸水平:AMP→IMP;GMP→XMP\u000b②核苷水平:腺苷→次黄苷;鸟苷→黄苷\u000b③碱基水平:腺嘌呤→次黄嘌呤;鸟嘌呤→黄嘌呤\u000b④最终:次黄嘌呤/黄嘌呤→黄嘌呤氧化酶→尿酸\u000b\u000b关键酶:\u000b• 腺苷脱氨酶、腺嘌呤脱氨酶(先脱氨)\u000b• 黄嘌呤氧化酶(含FAD/Mo)→催化最后两步氧化\u000b\u000b【痛风症生化基础】\u000b• 尿酸水溶性极低→血中过饱和→尿酸钠结晶\u000b• 结晶沉积关节/肾脏→炎症反应→剧烈疼痛\u000b• 原因:嘌呤代谢亢进/尿酸排出障碍/遗传酶缺陷\u000b\u000b【治疗】\u000b• 别嘌呤醇:抑制黄嘌呤氧化酶→减少尿酸生成\u000b• 促尿酸排泄药:丙磺舒\u000b• 饮食控制:低嘌呤食物", "kp": "nucleic_s0_0"}, {"id": "nucleic_short_7", "modI": 1, "q": "简述嘧啶核苷酸分解代谢的途径。", "a": "嘧啶分解经还原途径(先还原后开环):\u000b\u000b【胞嘧啶/尿嘧啶途径】\u000b①胞嘧啶→脱氨酶→尿嘧啶(先脱氨)\u000b②尿嘧啶+NADPH→二氢尿嘧啶脱氢酶→二氢尿嘧啶\u000b③二氢尿嘧啶+H2O→β-脲基丙酸\u000b④β-脲基丙酸+H2O→β-丙氨酸+NH3+CO2\u000b⑤β-丙氨酸→转氨→丙二酸半醛→乙酰CoA\u000b\u000b【胸腺嘧啶途径】\u000b①T+NADPH→二氢T→β-脲基异丁酸\u000b②β-脲基异丁酸→β-氨基异丁酸+NH3+CO2\u000b③β-氨基异丁酸→转氨→琥珀酰CoA\u000b\u000b特点:\u000b①先还原(需NADPH)后水解开环\u000b②终产物为水溶性β-氨基酸类(易排出,不沉淀)\u000b③与嘌呤不同:嘧啶分解不产生尿酸", "kp": "nucleic_s1_1"}, {"id": "nucleic_short_8", "modI": 3, "q": "简述核苷酸代谢相关的遗传性疾病及其生化基础。", "a": "核苷酸代谢遗传病体现关键酶的重要作用:\u000b\u000b【Lesch-Nyhan综合症】\u000b• 缺陷酶:HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)\u000b• 机制:嘌呤补救途径受阻→PRPP积累→从头合成亢进→尿酸大量产生\u000b• 症状:高尿酸血症(痛风)、自残行为、智力障碍、神经损害\u000b• 遗传:X连锁隐性\u000b\u000b【乳清酸尿症】\u000b• 缺陷酶:UMP合成酶(OPRT+OMP脱羧酶双功能酶)\u000b• 机制:嘧啶从头合成受阻→乳清酸积累→嘧啶核苷酸不足\u000b• 症状:巨幼红细胞性贫血(对叶酸/B12治疗无效)\u000b• 治疗:补充尿苷(绕过缺陷酶)\u000b\u000b【ADA缺陷→SCID】\u000b• 缺陷酶:腺苷脱氨酶(ADA)\u000b• 机制:腺苷/dAdo积累→dATP↑→抑制核糖核苷酸还原酶→dNTP不足→淋巴细胞不能增殖\u000b• 症状:严重联合免疫缺陷(SCID)\u000b• 意义:首个基因治疗成功的疾病(1990)\u000b\u000b【原发性痛风】\u000b• 原因:人缺乏尿酸酶→尿酸不能氧化为尿囊素→积累\u000b• 或:PRPP合成酶活性过高→嘌呤合成亢进\u000b• 症状:尿酸钠结晶沉积关节→剧痛\u000b\u000b共同点:均为单一酶缺陷→代谢中间物积累→毒性效应", "kp": "nucleic_s3_4"}, {"id": "nucleic_short_9", "modI": 2, "q": "简述核苷酸合成的抗代谢物及其作用机制。", "a": "抗代谢物是结构与正常代谢物类似、能干扰代谢的药物:\u000b\u000b【嘌呤类似物】\u000b• 6-巯基嘌呤(6-MP)→抑制IMP参与的反应→抗癌\u000b• 8-氮杂鸟嘌呤\u000b\u000b【嘧啶类似物】\u000b• 5-氟尿嘧啶(5-FU)→5-FdUMP→抑制胸苷酸合成酶→抗癌\u000b• 5-碘脱氧尿苷(疱疹净)→抗病毒\u000b\u000b【Gln类似物】\u000b• 重氮丝氨酸、6-重氮-5-氧-正亮氨酸(DON)→抑制Gln参与的反应\u000b\u000b【Asp类似物】\u000b• 羽田杀菌素(hadacidin)→抑制Asp参与的反应\u000b\u000b【叶酸类似物】\u000b• 氨甲喋呤(MTX)、氨基喋呤→不可逆抑制DHFR→阻断FH4→抑制一碳单位转移→阻断嘌呤/胸苷酸合成→抗癌/抗风湿\u000b\u000b原理:利用正常细胞与癌细胞/病原体核酸代谢差异选择性杀伤", "kp": "nucleic_s2_1"}], "calc": [{"id": "nucleic_calc_1", "modI": 2, "q": "试分析6-巯基嘌呤(6-MP)和5-氟尿嘧啶(5-FU)进入体内可能的代谢途径和作用机制。", "a": "6-MP抑制嘌呤合成(IMP→AMP/GMP);5-FU抑制胸苷酸合成(dTMP)", "steps": "【6-巯基嘌呤(6-MP)】\u000b①结构类似次黄嘌呤(巯基取代6位OH)\u000b②进入体内→与PRPP结合(HGPRT)→6-MP核苷酸\u000b③6-MP核苷酸抑制IMP参与的反应:\u000b  • 抑制IMP→AMP(腺苷酸代琥珀酸合成酶)\u000b  • 抑制IMP→GMP(IMP脱氢酶)\u000b  • 反馈抑制PRPP合成\u000b④结果:嘌呤核苷酸↓→核酸合成↓→抑制癌细胞增殖\u000b\u000b【5-氟尿嘧啶(5-FU)】\u000b①结构类似尿嘧啶(F取代5位H)\u000b②进入体内→补救途径→5-FdUMP\u000b③5-FdUMP与胸苷酸合成酶不可逆结合\u000b④阻断dUMP→dTMP→dTTP不足→DNA合成受阻\u000b⑤也可掺入RNA→干扰功能\u000b\u000b共同点:都是抗代谢物→干扰核酸合成→抗癌\u000b区别:6-MP作用于嘌呤,5-FU作用于嘧啶(dTMP)", "kp": "nucleic_s2_1"}, {"id": "nucleic_calc_2", "modI": 2, "q": "计算从PRPP开始合成1分子AMP和1分子GMP各消耗多少高能磷酸键？", "a": "AMP约消耗6~P;GMP约消耗7~P(从PRPP起算)", "steps": "【从PRPP→IMP】(共同路径)\u000b①PRPP+Gln→PRA:消耗PRPP的焦磷酸键(1个~P)\u000b②PRA+Gly→GAR:消耗1ATP\u000b③GAR→FGAR→FGAM:消耗1ATP\u000b④后续到IMP:共约5个~P\u000b\u000b【IMP→AMP】\u000bIMP+Asp+GTP→腺苷酸代琥珀酸→AMP+延胡索酸\u000b消耗1GTP(1个~P)\u000b\u000b【IMP→GMP】\u000bIMP+NAD+→XMP(0)\u000bXMP+Gln+ATP→GMP:消耗1ATP(1个~P)\u000b\u000b总计(从5-P核糖算):\u000b5-P核糖→PRPP:1ATP\u000bPRPP→IMP:约4ATP\u000bIMP→AMP:1GTP;IMP→GMP:1ATP\u000bAMP:约6~P;GMP:约7~P\u000b\u000b注意:从头合成能耗大,补救途径节能(仅1个~P)→细胞优先补救", "kp": "nucleic_s2_0"}, {"id": "nucleic_calc_3", "modI": 2, "q": "论述嘌呤核苷酸从头合成的调控机制。", "a": "嘌呤从头合成受多级反馈调控,防止过量合成", "steps": "【第一级:PRPP合成酶】\u000b• 受嘌呤核苷酸(IMP/AMP/GMP)反馈抑制\u000b• 受ADP/AMP激活(能量信号)\u000b• PRPP是嘌呤/嘧啶/补救途径共同前体\u000b\u000b【第二级:PRPP转酰胺酶(限速酶)】\u000b• 受AMP/GMP反馈抑制\u000b• 受PRPP浓度调控\u000b\u000b【第三级:IMP分支调控】\u000b• AMP过多→反馈抑制IMP→AMP支路(腺苷酸代琥珀酸合成酶)\u000b• GMP过多→反馈抑制IMP→GMP支路(IMP脱氢酶)\u000b\u000b【交叉调节】\u000b• GTP是AMP合成所需(腺苷酸代琥珀酸合成酶用GTP)\u000b• ATP是GMP合成所需(GMP合成酶用ATP)\u000b• 高ATP→促进GMP生成;高GTP→促进AMP生成\u000b→维持嘌呤核苷酸池平衡\u000b\u000b意义:多级反馈调控→精确控制核苷酸合成→避免浪费/防止代谢紊乱", "kp": "nucleic_s2_3"}, {"id": "nucleic_calc_4", "modI": 3, "q": "论述核苷酸代谢与糖/脂/蛋白质代谢的联系(四大物质代谢的整合)。", "a": "核苷酸代谢与三大物质代谢通过前体和产物紧密联系", "steps": "【核苷酸合成前体来自其他代谢】\u000b①PRPP的5-P核糖→来自PPP(糖代谢)\u000b②嘌呤/嘧啶的N→来自Gln/Asp(氨基酸代谢)\u000b③Gly/Asp→嘌呤环的C/N(氨基酸代谢)\u000b④CO2→羧基来源(呼吸代谢)\u000b⑤一碳单位→来自Ser/Gly分解(氨基酸代谢)\u000b⑥嘧啶的Asp→来自OAA(转氨,TCA中间物)\u000b\u000b【核苷酸分解产物进入其他代谢】\u000b①嘌呤→尿酸→排出(人类)\u000b②嘧啶→β-丙氨酸→乙酰CoA→TCA\u000b③胸腺嘧啶→β-氨基异丁酸→琥珀酰CoA→TCA\u000b④戊糖-1-P→戊糖-5-P→PPP\u000b\u000b【核苷酸是辅酶/能量物质前体】\u000b①ATP/GTP→能量代谢核心\u000b②AMP→NAD+/NADP+/FAD/CoA→三大代谢的辅酶\u000b③核苷酸→信号分子(cAMP/cGMP)→代谢调节\u000b\u000b总结:核苷酸代谢通过前体供给和产物回补,与糖/脂/蛋白质代谢形成完整网络,TCA是枢纽", "kp": "nucleic_s3_6"}, {"id": "nucleic_calc_5", "modI": 2, "q": "计算嘧啶从头合成中,从氨甲酰磷酸到UMP各步骤消耗的高能磷酸键总数,并与嘌呤合成比较。", "a": "氨甲酰磷酸→UMP直接消耗0~P(但从头合计约3~P)", "steps": "嘧啶从头合成能耗:\u000b①Gln+CO2+2ATP→氨甲酰磷酸(CPS-II):消耗2~P\u000b②氨甲酰磷酸+Asp→氨甲酰Asp(ATCase):0\u000b③→二氢乳清酸→乳清酸:0(仅氧化还原)\u000b④乳清酸+PRPP→OMP:0(PRPP的~P已付)\u000b⑤OMP→UMP:0(脱羧)\u000b\u000b从氨甲酰磷酸→UMP直接消耗:0~P\u000b但从CO2/Gln/Asp→UMP:2~P(CPS-II的2ATP)\u000b\u000b若计入PRPP:\u000b5-P核糖→PRPP:1ATP\u000b\u000b总计(从头):\u000b嘧啶UMP:约3~P(CPS-II的2ATP+PRPP的1ATP)\u000b嘌呤IMP:约5~P\u000b\u000b比较:\u000b①嘌呤合成能耗>嘧啶(5~P vs 3~P)\u000b②嘧啶先合成环再连PRPP→更节省\u000b③CTP合成:UTP+Gln+ATP→CTP,再耗1~P", "kp": "nucleic_s2_3"}], "term": [{"id": "nucleic_term_1", "modI": 0, "term": "核酸酶(Nuclease)", "def": "①催化核酸磷酸二酯键水解的酶类（定义）。②按底物分类：核糖核酸酶(RNase)作用于RNA、脱氧核糖核酸酶(DNase)作用于DNA（底物分类）。③按作用位点：核酸内切酶(切分子内部)、核酸外切酶(从末端逐个水解)（位点分类）。④举例：蛇毒磷酸二酯酶→5'-核苷酸、牛脾磷酸二酯酶→3'-核苷酸、限制性核酸内切酶EcoRⅠ识别特定序列（举例）。⑤生理意义：参与核酸降解、基因工程(限制酶)、DNA修复等（意义）。", "kps": "①定义(1分)②底物分类(1分)③位点分类(1分)④举例(1分)⑤意义(1分)", "kp": "nucleic_s0_2"}, {"id": "nucleic_term_2", "modI": 1, "term": "限制性核酸内切酶(Restriction Endonuclease)", "def": "①能识别DNA特定碱基序列并在特定位点切割DNA的核酸内切酶（定义）。②识别序列多为4-8bp回文结构，如EcoRⅠ识别GAATTC（识别）。③切割方式：产生粘性末端或平末端（切割）。④来源：细菌中防御外源DNA(噬菌体)的天然免疫系统（来源）。⑤应用：基因工程的分子剪刀——DNA重组、分子克隆、基因图谱构建的核心工具（应用）。", "kps": "①定义(1分)②回文序列(1分)③粘性/平末端(1分)④细菌防御来源(1分)⑤基因工程应用(1分)", "kp": "nucleic_s1_0"}, {"id": "nucleic_term_3", "modI": 0, "term": "尿酸(Uric Acid)", "def": "①嘌呤碱基(腺嘌呤、鸟嘌呤)分解代谢的最终产物（定义）。②结构：嘌呤环2,6,8位氧化的三羟基嘌呤（结构）。③生成：次黄嘌呤/黄嘌呤经黄嘌呤氧化酶氧化生成（生成）。④特点：水溶性极低→易过饱和结晶（特点）。⑤病理：尿酸过多→尿酸钠结晶沉积关节→痛风症；HGPRT缺陷→Lesch-Nyhan综合症可致尿酸过多（病理）。", "kps": "①定义(1分)②结构(1分)③生成(1分)④水溶性低(1分)⑤痛风病理(1分)", "kp": "nucleic_s0_5"}, {"id": "nucleic_term_4", "modI": 0, "term": "黄嘌呤氧化酶(Xanthine Oxidase)", "def": "①催化次黄嘌呤→黄嘌呤→尿酸两步氧化反应的酶（定义）。②辅基：含FAD、钼(Mo)、铁-硫簇(Fe-S)（辅基）。③产物：每步氧化产生H2O2副产物（产物）。④意义：是嘌呤分解代谢终末限速酶，决定尿酸生成速率（意义）。⑤抑制：别嘌呤醇(竞争性抑制)用于治疗痛风（临床）。", "kps": "①定义(1分)②FAD/Mo/FeS(1分)③H2O2(1分)④限速酶意义(1分)⑤别嘌呤醇(1分)", "kp": "nucleic_s0_6"}, {"id": "nucleic_term_5", "modI": 0, "term": "痛风症(Gout)", "def": "①因尿酸在体内过多积累导致尿酸钠结晶沉积关节、肾脏等处的代谢性疾病（定义）。②生化基础：嘌呤代谢亢进、尿酸排泄障碍或相关酶缺陷(HGPRT/PRPP合成酶)（病因）。③症状：关节剧痛(常在脚拇趾)、炎症、尿酸性肾结石（症状）。④治疗：别嘌呤醇(抑制黄嘌呤氧化酶减少尿酸生成)、丙磺舒(促尿酸排泄)（治疗）。⑤预防：低嘌呤饮食、多饮水（预防）。", "kps": "①定义(1分)②生化基础(1分)③症状(1分)④治疗(1分)⑤预防(1分)", "kp": "nucleic_s0_7"}, {"id": "nucleic_term_6", "modI": 1, "term": "PRPP(5-磷酸核糖焦磷酸)", "def": "①5-磷酸核糖焦磷酸，核苷酸合成的关键中间物（定义）。②合成：5-磷酸核糖+ATP经PRPP合成酶(磷酸核糖焦磷酸激酶)生成（合成）。③功能：嘌呤从头合成、嘧啶从头合成和补救途径的共同核糖磷酸供体（功能）。④调控：PRPP合成酶受嘌呤/嘧啶核苷酸反馈抑制（调控）。⑤重要性：PRPP浓度是核苷酸合成速率的决定因素之一（重要性）。", "kps": "①定义(1分)②合成(1分)③三途径共同前体(1分)④反馈抑制(1分)⑤重要性(1分)", "kp": "nucleic_s1_5"}, {"id": "nucleic_term_7", "modI": 1, "term": "从头合成(De Novo Synthesis)", "def": "①以简单前体(氨基酸、CO2、NH3、核糖磷酸、一碳单位)为原料合成核苷酸的途径（定义）。②原料：嘌呤环由Gly/Asp/Gln/CO2/一碳单位构成；嘧啶环由Asp/Gln/CO2构成（原料）。③特点：耗能大、需多种酶、受严格反馈调控（特点）。④与补救途径的区别：从头合成利用简单前体从头构建，补救途径利用现成碱基/核苷（区别）。⑤主要部位：肝脏（嘌呤）；多种组织（嘧啶）（部位）。", "kps": "①定义(1分)②原料(1分)③特点(1分)④与补救区别(1分)⑤部位(1分)", "kp": "nucleic_s1_4"}, {"id": "nucleic_term_8", "modI": 3, "term": "补救途径(Salvage Pathway)", "def": "①利用现成碱基或核苷与PRPP/核糖-1-磷酸重新合成核苷酸的途径（定义）。②途径：碱基+PRPP→核苷酸(磷酸核糖转移酶)；或碱基+核糖-1-P→核苷→核苷酸(核苷磷酸化酶+核苷激酶)（途径）。③关键酶：APRT(腺嘌呤磷酸核糖转移酶)、HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)（关键酶）。④意义：节约能量(1个~P vs 从头合成5-7个~P)、脑组织几乎全依赖补救途径（意义）。⑤病理：HGPRT缺陷→Lesch-Nyhan综合症（病理）。", "kps": "①定义(1分)②两种途径(1分)③关键酶(1分)④意义(1分)⑤病理(1分)", "kp": "nucleic_s3_2"}, {"id": "nucleic_term_9", "modI": 3, "term": "HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)", "def": "①催化次黄嘌呤/鸟嘌呤+PRPP→IMP/GMP+PPi的补救合成酶（定义）。②功能：嘌呤补救途径的关键酶（功能）。③意义：脑组织依赖此酶维持核苷酸池(脑缺从头合成酶)（意义）。④缺陷：Lesch-Nyhan综合症——X连锁隐性遗传，表现为尿酸过多(痛风)、自残行为、智力障碍、神经损害（缺陷）。⑤机制：HGPRT缺陷→补救受阻→PRPP积累→从头合成亢进→尿酸大量生成（机制）。", "kps": "①定义(1分)②功能(1分)③脑组织意义(1分)④Lesch-Nyhan(1分)⑤机制(1分)", "kp": "nucleic_s3_2"}, {"id": "nucleic_term_10", "modI": 3, "term": "Lesch-Nyhan综合症", "def": "①HGPRT(次黄嘌呤-鸟嘌呤磷酸核糖转移酶)完全或严重缺陷导致的X连锁隐性遗传病（定义）。②生化机制：补救途径受阻→PRPP积累→嘌呤从头合成亢进→尿酸大量产生→痛风（生化）。③症状：高尿酸血症(痛风)、自残行为(咬手指/唇)、智力发育迟缓、锥体外系神经症状（症状）。④意义：证明嘌呤补救途径对神经系统(尤其脑)的关键作用（意义）。⑤诊断/治疗：测定HGPRT活性、别嘌呤醇控制尿酸（诊疗）。", "kps": "①HGPRT缺陷(1分)②生化机制(1分)③症状(1分)④意义(1分)⑤诊疗(1分)", "kp": "nucleic_s3_3"}, {"id": "nucleic_term_11", "modI": 2, "term": "IMP(次黄苷酸)", "def": "①次黄苷酸，嘌呤核苷酸从头合成的第一个完整核苷酸产物（定义）。②结构：次黄嘌呤碱基+核糖+磷酸（结构）。③作用：作为嘌呤合成母体→分支生成AMP和GMP（作用）。④转化：IMP+Asp+GTP→AMP；IMP+NAD+→XMP→GMP（转化）。⑤意义：IMP是嘌呤从头合成与分支合成的分水岭，其浓度受严格调控（意义）。", "kps": "①定义(1分)②结构(1分)③母体作用(1分)④转化(1分)⑤分水岭意义(1分)", "kp": "nucleic_s2_0"}, {"id": "nucleic_term_12", "modI": 2, "term": "一碳单位(One-carbon Unit)", "def": "①某些氨基酸(甘氨酸、丝氨酸、组氨酸、甲硫氨酸)分解代谢产生的含一个碳原子的基团（定义）。②种类：甲基(-CH3)、亚甲基(-CH2-)、次甲基(-CH=)、甲酰基(-CHO)、亚氨甲基(-CH=NH)（种类）。③载体：四氢叶酸(FH4)、S-腺苷甲硫氨酸(SAM)（载体）。④来源：Ser、Gly、His、Met等（来源）。⑤作用：嘌呤合成(C2/C8来自N10-CHO-FH4)、胸苷酸合成(dTMP的甲基来自N5,N10-CH2-FH4)（作用）。", "kps": "①定义(1分)②种类(1分)③FH4/SAM载体(1分)④来源(1分)⑤嘌呤/dTMP合成(1分)", "kp": "nucleic_s2_2"}, {"id": "nucleic_term_13", "modI": 2, "term": "四氢叶酸(FH4)", "def": "①叶酸(维生素B9)的活性形式，一碳单位的重要载体（定义）。②结构：叶酸还原(二氢叶酸还原酶催化)→FH4（结构）。③作用：N5、N10或N5,N10位结合一碳单位→参与嘌呤、胸苷酸合成（作用）。④再生：FH2→二氢叶酸还原酶→FH4（再生）。⑤临床：叶酸类似物(MTX)抑制DHFR→阻断FH4→抑制核酸合成→抗癌；叶酸缺乏→巨幼红细胞性贫血（临床）。", "kps": "①定义(1分)②活性形式(1分)③一碳载体(1分)④DHFR再生(1分)⑤临床(1分)", "kp": "nucleic_s2_2"}, {"id": "nucleic_term_14", "modI": 2, "term": "二氢叶酸还原酶(DHFR)", "def": "①催化二氢叶酸(FH2)还原为四氢叶酸(FH4)的酶（定义）。②功能：再生FH4→维持一碳单位代谢→保证嘌呤和胸苷酸合成（功能）。③辅酶：NADPH（辅酶）。④抑制剂：氨甲喋呤(MTX)、氨基喋呤(叶酸类似物)→不可逆结合→抑制FH4再生（抑制）。⑤临床意义：DHFR是抗癌/抗细菌/抗疟疾药物的重要靶点（意义）。", "kps": "①定义(1分)②功能(1分)③NADPH(1分)④MTX抑制(1分)⑤药物靶点(1分)", "kp": "nucleic_s2_2"}, {"id": "nucleic_term_15", "modI": 2, "term": "抗代谢物(Antimetabolite)", "def": "①结构与天然代谢物类似、能竞争性干扰正常代谢过程的物质（定义）。②原理：冒充正常底物→抑制关键酶→阻断代谢途径（原理）。③分类：嘌呤类似物(6-MP)、嘧啶类似物(5-FU)、叶酸类似物(MTX)、氨基酸类似物(重氮丝氨酸、DON)（分类）。④应用：抗癌(抑制快速分裂细胞核酸合成)、抗病毒、抗菌（应用）。⑤代表：Elion和Hitchings因抗代谢物药物设计获1988年诺贝尔奖（代表）。", "kps": "①定义(1分)②原理(1分)③分类(1分)④应用(1分)⑤诺贝尔奖(1分)", "kp": "nucleic_s2_1"}, {"id": "nucleic_term_16", "modI": 0, "term": "β-丙氨酸/β-氨基异丁酸", "def": "①嘧啶碱基分解代谢的最终产物（定义）。②胞嘧啶/尿嘧啶→β-丙氨酸；胸腺嘧啶→β-氨基异丁酸（产物）。③特点：水溶性开环氨基酸类，可直接排出或进一步代谢（特点）。④去向：β-丙氨酸→转氨→乙酰CoA→TCA；β-氨基异丁酸→转氨→琥珀酰CoA→TCA（去向）。⑤与嘌呤的区别：嘧啶分解不产生尿酸(水溶性好、易排出)（区别）。", "kps": "①定义(1分)②两种产物(1分)③特点(1分)④去向(1分)⑤与嘌呤区别(1分)", "kp": "nucleic_s0_1"}, {"id": "nucleic_term_17", "modI": 2, "term": "核糖核苷酸还原酶(Ribonucleotide Reductase)", "def": "①催化核糖核苷酸(NDP)还原为脱氧核糖核苷酸(dNDP)的酶（定义）。②底物：NDP(二磷酸核糖核苷)，非NMP/NTP（底物）。③机制：含铁-硫簇和酪氨酸自由基，利用硫氧还蛋白作还原剂（机制）。④再生：硫氧还蛋白(SH)2→S-S，由硫氧还蛋白还原酶+NADPH再生（再生）。⑤意义：提供dNTP前体→DNA合成；受调控→保证脱氧核苷酸池平衡（意义）。", "kps": "①定义(1分)②底物NDP(1分)③机制(1分)④硫氧还蛋白再生(1分)⑤DNA前体意义(1分)", "kp": "nucleic_s2_6"}, {"id": "nucleic_term_18", "modI": 2, "term": "硫氧还蛋白(Thioredoxin)", "def": "①含-SH的氧化还原蛋白，作为核糖核苷酸还原酶的还原剂（定义）。②机制：硫氧还蛋白(SH)2被氧化为S-S形式，同时还原核糖核苷酸为脱氧核糖核苷酸（机制）。③再生：硫氧还蛋白还原酶+NADPH→还原S-S为(SH)2（再生）。④功能：维持细胞内还原环境，参与核苷酸还原等多种氧化还原反应（功能）。⑤意义：是连接NADPH与脱氧核苷酸合成的关键中间体（意义）。", "kps": "①定义(1分)②氧化还原机制(1分)③再生(1分)④功能(1分)⑤意义(1分)", "kp": "nucleic_s2_6"}, {"id": "nucleic_term_19", "modI": 3, "term": "胸苷酸合成酶(Thymidylate Synthase)", "def": "①催化dUMP甲基化为dTMP的酶（定义）。②反应：dUMP+N5,N10-CH2-FH4→dTMP+FH2（反应）。③甲基供体：N5,N10-亚甲基四氢叶酸(一碳单位)（甲基供体）。④产物：FH2需DHFR还原为FH4再生（再生）。⑤临床：5-FU→5-FdUMP→不可逆抑制此酶→抗癌（临床）。", "kps": "①定义(1分)②反应(1分)③甲基供体(1分)④FH2再生(1分)⑤5-FU抑制(1分)", "kp": "nucleic_s3_1"}, {"id": "nucleic_term_20", "modI": 1, "term": "氨甲酰磷酸合成酶II(CPS-II)", "def": "①嘧啶合成中催化Gln+CO2+2ATP→氨甲酰磷酸的酶（定义）。②部位：细胞质(与尿素循环的CPS-I在线粒体不同)（部位）。③氮源：利用Gln酰胺氮(CPS-I利用NH3)（氮源）。④调控：受UMP反馈抑制（调控）。⑤意义：嘧啶合成的限速步骤之一，为嘧啶环提供氨甲酰基（意义）。", "kps": "①定义(1分)②细胞质(1分)③Gln氮源(1分)④UMP抑制(1分)⑤意义(1分)", "kp": "nucleic_s1_6"}, {"id": "nucleic_term_21", "modI": 0, "term": "尿酸酶(Urate Oxidase/Uricase)", "def": "①催化尿酸氧化为尿囊素(allantoin)的酶（定义）。②反应：尿酸+O2+H2O→尿囊素+CO2+H2O2（反应）。③产物：尿囊素水溶性远高于尿酸→易排出（产物）。④分布：多数哺乳动物、两栖类有；人类和灵长类、鸟类、爬行类在进化中丢失此酶基因(假基因化)（分布）。⑤意义：人缺乏尿酸酶→尿酸是嘌呤代谢终产物→水溶性低→易结晶→痛风（意义）。", "kps": "①定义(1分)②反应(1分)③尿囊素更水溶(1分)④人/灵长类缺乏(1分)⑤痛风联系(1分)", "kp": "nucleic_s0_2"}, {"id": "nucleic_term_22", "modI": 2, "term": "乳清酸尿症(Orotic Aciduria)", "def": "①UMP合成酶缺陷导致的嘧啶核苷酸从头合成障碍的遗传病（定义）。②缺陷酶：UMP合成酶是双功能酶——含乳清酸磷酸核糖转移酶(OPRT)+乳清苷酸脱羧酶(OMP脱羧酶)两种活性（缺陷酶）。③机制：嘧啶从头合成受阻→乳清酸大量积累→尿中排出；嘧啶核苷酸不足→核酸合成障碍（机制）。④症状：巨幼红细胞性贫血(对叶酸/VB12治疗无效)、生长发育迟缓（症状）。⑤治疗：补充尿苷(经补救途径生成UMP,绕过缺陷步骤)（治疗）。", "kps": "①定义(1分)②UMP合成酶双功能(1分)③乳清酸积累(1分)④巨幼贫血(1分)⑤尿苷治疗(1分)", "kp": "nucleic_s2_5"}, {"id": "nucleic_term_23", "modI": 3, "term": "腺苷脱氨酶缺陷/SCID(ADA Deficiency)", "def": "①腺苷脱氨酶(ADA)缺陷导致的严重联合免疫缺陷(SCID)（定义）。②ADA功能：催化腺苷→次黄苷、脱氧腺苷→脱氧次黄苷(嘌呤分解代谢)（功能）。③机制：ADA缺陷→腺苷/脱氧腺苷积累→经激酶→dATP↑→dATP别构抑制核糖核苷酸还原酶→dNTP不足→DNA合成受阻→淋巴细胞不能增殖（机制）。④症状：T/B淋巴细胞都缺陷→严重联合免疫缺陷→反复严重感染（症状）。⑤意义：1990年首个基因治疗成功的疾病(Ashanti DeSilva)（意义）。", "kps": "①定义(1分)②ADA功能(1分)③dATP抑制RNR机制(2分)④SCID症状(1分)⑤基因治疗里程碑(1分)", "kp": "nucleic_s3_0"}, {"id": "nucleic_term_24", "modI": 2, "term": "谷氧还蛋白(Glutaredoxin)", "def": "①含-SH的小分子氧化还原蛋白，作为核糖核苷酸还原酶的另一电子供体（定义）。②机制：谷氧还蛋白(SH)2被氧化为S-S，同时还原核糖核苷酸为脱氧核糖核苷酸（机制）。③电子来源：利用谷胱甘肽(GSH)作还原剂→与硫氧还蛋白(利用NADPH+硫氧还蛋白还原酶)并列的还原系统（电子来源）。④功能：与硫氧还蛋白共同维持核糖核苷酸还原酶的还原力供应（功能）。⑤意义：体现了细胞氧化还原系统的冗余性和灵活性（意义）。", "kps": "①定义(1分)②氧化还原机制(1分)③GSH电子来源(1分)④与硫氧还蛋白并列(1分)⑤意义(1分)", "kp": "nucleic_s2_6"}, {"id": "nucleic_term_25", "modI": 2, "term": "dUTPase(dUTP焦磷酸酶)", "def": "①催化dUTP水解为dUMP+PPi的酶（定义）。②作用一：降低dUTP浓度→防止dUTP代替dTTP掺入DNA(避免U:G错配、DNA损伤)（防错配作用）。③作用二：生成的dUMP是胸苷酸合成酶底物→dTMP合成前体（提供前体）。④重要性：dUTP/dTTP比值是DNA合成保真性的关键决定因素（重要性）。⑤联系：与胸苷酸合成酶、DHFR共同维持dTMP池→保证DNA合成所需dTTP（联系）。", "kps": "①定义(1分)②防dUTP掺入(2分)③提供dUMP(1分)④保真性意义(1分)⑤与dTMP合成联系(1分)", "kp": "nucleic_s2_5"}, {"id": "nucleic_term_26", "modI": 3, "term": "腺苷激酶(Adenosine Kinase)", "def": "①催化腺苷+ATP→AMP+ADP的酶（定义）。②功能：腺苷补救合成AMP的直接途径(不需PRPP,与APRT利用腺嘌呤+PRPP不同)（功能）。③意义：腺苷激酶+腺苷脱氨酶共同决定细胞内腺苷的浓度→腺苷是重要的信号分子(调节血管舒张、神经活动等)（意义）。④与其他补救途径的关系：APRT(腺嘌呤+PRPP→AMP)、HGPRT(次黄嘌呤/鸟嘌呤+PRPP)、腺苷激酶(腺苷+ATP→AMP)三条嘌呤补救途径（关系）。⑤临床：腺苷激酶抑制剂可升高腺苷浓度→用于抗炎、镇痛、抗癫痫等研究（临床）。", "kps": "①定义(1分)②腺苷补救(1分)③腺苷信号调节(1分)④三补救途径(1分)⑤临床意义(1分)", "kp": "nucleic_s3_2"}], "preview": null, "appcards": []};